INSERT INTO public.training_library (age_group, training_number, exercises)
VALUES
('O9', 1, '{"session_a": [{"type": "test", "title": "WENDBAARHEIDSTEST 1", "content": "Voor deze test wordt in het strafschopgebied, tussen de doellijn\nen de rand van het gebied, een parcours ( zie tekening) uitgezet.\nHet protocol voor deze test luidt als volgt:\nDe test start vanuit buikligging. Vervolgens wordt het hele traject\nin korte sprintjes, van pylon naar pylon, afgelegd.\nDe pylonen worden daarbij,tot het bereiken van de finish, telkens\nzo kort mogelijk gerond.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen:8\nAfstand tussen de pylonen:gebruik de\naangegeven lijnen en verdeel de tussenliggende\nruimte gelijkmatig\nSchrijfbenodigdheden\nAanwijzingen\n- ontwikkel, zowel heen als terug, een zo\nhoog mogelijke snelheid\n- draai kort om de pylon\n- neem minimaal 2-3 minuten rust tussen\ntwee testen"}, {"type": "techniek", "title": "STAP 2.1 A: AANBIEDEN, HEEN/TERUG (ZELFDE/ANDERE BEEN) IN LIJNVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"voorwaarts\" aan.\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- speler 2 neemt de bal met de binnenkant van de linkervoet aan.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich \"voorwaarts\" aan.\n- speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- speler 1 neemt de bal met de binnenkant van de linkervoet aan,\netc.\nVariatie in uitvoering:\n- idem, maar nu aannemen en spelen met dezelfde voet\nVariatie in aanbieden:\n- achterwaarts\n- naar rechts\n- naar links\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 2\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAannemen:\n- bal moet voor je liggen, maar binnen bereik.\n- snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet.\nSTAP 1: PARCOURS DRIBBELEN\nMethodiek\nDe spelers slalommen dribbelend het hele parcours door.\nVariatie in aanbieden:\n- varieer in uitvoeringssnelheid\n- varieer onderlinge afstand pylonen\n- voer de oefening in wedstrijdvorm uit.\nVariatie\nVariatie 4: Parcours dribbelen met zowel rechter als linker voet.\nMaterialen\nAantal spelers: 4-10\nAantal ballen: elke speler 1 bal\nAantal pylonen: 8\nOnderlinge afstand pylonen: 2 a 3 meter\nAanwijzingen\nSpelers coachen op:\n- houd de bal dichtbij je, maar niet onder je\n- probeer de bal zoveel mogelijk te raken\n- probeer de bal bij iedere stap te raken, dan\nkun je de bal ook beter sturen."}, {"type": "techniek", "title": "PARCOURS DRIBBELEN EN AFWERKEN", "content": "De spelers slalommen dribbelend het hele parcours door en werk\naf op doel.\nVariatie in aanbieden:\n- Varieer in uitvoeringssnelheid\n- Varieer onderlinge afstand pylonen.\n- Voer de oefening in wedstrijdvorm uit.\nVariatie\nVariatie 4: Parcours dribbelen met rechter en linker voet.\nMaterialen\nAantal spelers: 4-10\nAantal ballen: elke speler 1 bal\nAantal pylonen: 8\nDoelen: 2\nOnderlinge afstand pylonen: 2 a 3 meter\nAanwijzingen\nSpelers coachen op:\n- Houdt de bal dichtbij je, maar niet onder je.\n- Probeer de bal zoveel mogelijk te raken.\n- Probeer de bal bij iedere stap te raken, dan\nkun je de bal ook beter sturen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "SIGNAAL SPEL", "content": "Alle spelers staan met een bal naast elkaar in één rij voor de\ntrainer. Vooraf spreekt de trainer met de spelers bepaalde tekens\naf. Op een teken van de trainer voeren de spelers bijbehorende\nopdracht uit.\nVoorbeelden zijn:\n- dribbelen op de plaats door de bal links rechts te tikken\n- dribbelen naar links of rechts.\n- voor uit of achteruit te dribbelen.\n- voeten beurtlinks links rechts op de bal zetten.\n- etc.\nMaterialen\nTijd: 10-15 min\nPylonen: gebruik hiervoor de ruimte die u voor u\ntraining ter beschikking heeft.\nBallen: voor iedere speler een bal.\nAanwijzingen\n- zorg dat elke speler voldoende ruimte heeft\nvoor het uitvoeren van de oefening.\n- houdt controle over de bal. Let er op dat de\nspelers de bal dichtbij zich houden.\n- doe eerst oefeningen zonder bal.\nSTAP 2.1 A: ZIJWAARTS AANBIEDEN, HEEN/TERUG IN LIJNVORM\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal met de binnenkant van de linkervoet aan.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich \"naar rechts aan\"\n- speler 2 speelt de bal met de binnenkant van de linkervoet\n- speler 1 neemt de bal met de binnenkant van de rechtervoet aan.\nC. Speler 1 speelt naar speler 2\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\nidem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 4\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2 A: DRIBBELEN (LIJN/STROOMVORM, HEEN/TERUG)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2.\n- Speler 1 loopt achter de bal aan naar speler 3 en sluit achter\nhem aan.\nB. Speler 2 dribbelt naar speler 1.\n- Speler 2 neemt de bal met rechts aan en dribbelt de bal, met de\nbuitenkant van de rechtervoet, terug.\n- Speler 2 neemt de plaats in van speler 1, etc.\nVariatie in uitvoering:\n- met links aannemen en dribbelen.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAannemen van de bal:\n- snelheid houden na de aanname voor de\nvolgende actie.\nDribbelen van de bal:\n- speelbeen: Bal steeds zodanig en zo vaak\nraken dat hij in het looptempo en in goede\nrichting kan worden meegenomen \"bal aan\nelastiekje\".\n- raakvlak: Het beroeren van de bal\nafwisselend met wreef, binnen- en buitenkant\nvan de voet afhankelijk van\nrichtingsverandering.\n- over de bal heen kijken.\n(4 : 1) OEFENING 1\nMethodiek\nVier aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\n3x bal afnemen is wisselen van taak met de aanvaller die het\nlangst niet in het midden heeft gestaan.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 5\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 4 spelers nemen positie in op de 4 zijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de vier\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O9', 2, '{"session_a": [{"type": "warming_up", "title": "DE OOIEVAAR", "content": "Is een oefening, waarbij de speler(s) de stap van één van de\nonderstaande technieken, op de plaats, moet(en)uitvoeren.\nBelangrijk hierbij is dat de speler na 5 skippings gedurende 5 tot\n10 seconden op zijn gehele voet stil blijft staan. Als de speler dit\nniet volhoud dan moet hij een sprint maken tot aan de 16-\nmeterlijn of tot bij de trainer.\n1. Skipping (Stap 3)\n2. Hielaanslag ( Stap 1)\nOpgelet!\nDit is een aanleervorm, waarbij de speler de stabiliteit in zijn been\n(knie/enkel), maar ook dat van zijn bovenlichaam (heup/borst)\nleert te beheersen.\nDifferentiatie:\n- Op de bal van de voet stilstaan\n- Uitvoering in voorwaartse richting.\n- Variëren in aantal skippings.\nMaterialen\nAantal spelers: gehele team\nOrganisatie:\nDe spelers staan kris kras door elkaar in het 16-\nmeter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSTAP 2.2 A: AANBIEDEN, HEEN/TERUG IN LIJNVORM COMBINATIE\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 speelt de bal met de binnenkant van de linker-\n/rechtervoet.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 2 kaatst de bal met de binnenkant van de linker-\n/rechtervoet terug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 kaatst de bal met de binnenkant van de linker-\n/rechtervoet.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Schaar (Stap 3)\n- Akka (buiten-binnen) (Stap 1)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 1: Het aanleren van de techniek Schaar (Stap 4).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nLIJNDRIBBEL 2:1 ZONDER DOEL\nMethodiek\nd.w.z. dat 2 aanvallers d.m.v. samenspel/ een persoonlijke actie\neen verdediger uitspelen, om daarna te scoren door de bal over\nde lijn te dribbelen.\nOpgelet!\nDe 2 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nMet de afgepakte bal eerst het recht van aanval halen door de bal\nterug te spelen naar de tweede man.\nBij de verdedigende partij gaat er direct één speler het veld uit.\nMaterialen\nAantal spelers: 4 (3+1)\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 15m bij 10m\nE-pupillen: 18m bij 12m\nD-pupillen: 20m bij 15m\nC-,B-,A-junioren: 25m bij 20m\nOrganisatie:\nHet spel wordt gespeeld met 3 spelers in het\nveld en één speler (verdediger)daarbuiten. Bij\neen afgepakte bal moet, voordat het spel hervat\nkan worden, eerst het recht van aanval ( d.w.z.\ner wordt gewisseld van taak/ speler) gehaald\nworden.\nAanwijzingen\nAanvallers coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- keuzes maken aan de bal( 1:1 of overspelen)\n- rekening houden, bij het innemen van een\naanvallende positie, met de omschakeling bij\nbalverlies(restverdediging)\nVerdediger coachen op:\n- rekening houden met een goed zicht op de\npositie van de beide aanvallers bij het\ninnemen van een verdedigende positie(open\nstaan)\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}], "session_b": [{"type": "warming_up", "title": "POORT TIKKERTJE", "content": "1 speler probeert als tikker de anderen te tikken. Een getikte speler blijft\nwijdbeens staan. Elke \"vrije speler\" kan hen weer \"vrij\" tikken door de bal onder\nhun poortje door te spelen en direct weer onder controle mee te nemen.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 6-8 of meer spelers\nPylonen: 4 om het speelveld af te bakenen.\nBallen: iedere speler een bal.\nSTAP 2.2 A: AANBIEDEN VOOR/ACHTERWAARTS, IN LIJNVORM\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"achterwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1, etc.\n- speler 1 biedt zich \"voorwaarts\" aan\n- speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"achterwaarts\" aan\n- speler 1 kaatst de bal met de binnenkant van de rechtervoet\nterug, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nAantal ballen: 1\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "STAP 1: OVERSTEEK SPEL", "content": "Elke speler heeft 1 bal en op een teken van de trainer dribbelen\nde spelers naar de overkant. Onderweg probeert de \"balafpakker\"\nde ballen van de andere spelers uit het vierkant te schieten.\n- bal kwijt, dan wordt je ook \"balafpakker\".\n- de speler die overblijft is winnaar.\nVariatie in aanbieden:\n- elke speler start met 3 punten. Bij balverlies gaat er telkens 1\npunt af.\n- bij 0 punten is de speler af.\n- winnaar is degene die over blijft.\nMaterialen\nAantal spelers: 6-8\nAantal ballen: elke speler 1 bal, behalve de\nbalafpakker\nHesjes: de balafpakker Aantal pylonen: 6\nAfstand tussen de pylonen: speelveld: ongeveer\n10 bij 15 meter\nAanwijzingen\nSpelers coachen op:\n- de bal dichtbij je houden\n- de bal goed afschermen\n- een andere kant opgaan als de tikker naar\nje toekomt\n- probeer snel de overkant te bereiken."}, {"type": "techniek", "title": "IN STROOMVORM (2)", "content": "Deze oefenvorm wordt uitgevoerd met twee groepen binnen een\nafgebakend vak.\nA. Speler 1 passed de bal, schuin over de breedte, op de vragende\nspeler 2.\nB. Speler 2 krijgt de bal zodanig en met de juiste snelheid\naangespeeld, dat hij hem direct op het doel kan schieten.\nOpgelet!\nDe spelers moeten de bal in één keer schieten en vooral niet stil\ngaan staan om te schieten.\nVariatie in uitvoering:\n- Idem andersom met het andere been.\n- Vergroot/verklein de afstand ten opzichte van het schietpunt en/\nof het vak.\nMaterialen\nAantal spelers: 8- 12\nAantal ballen: 4-6\nAantal pylonen: 6\nBreedte speelveld: 20m\nDoelen: 2\nF-,E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen:\nStartafstand vanaf doel:\n2e jaars F-pupillen: 11 m\n1e jaars E-pupillen: 13 m\n2e jaars E-pupillen: 15 m\nD-pupillen: 17 m\nC-,B-,A-junioren: >19 m\nSchietafstand vanaf doel:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Nadat de speler geschoten heeft haalt hij zijn\neigen bal op en sluit achter in de andere rij aan.\n- Nadat een speler de beginpass heeft gegeven\nsluit hij aan in de rij aan de andere zijde van het\ndoel.\nAanwijzingen\nSpelers coachen op:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O9', 3, '{"session_a": [{"type": "warming_up", "title": "BALGOOCHELAAR", "content": "Oefeningen, waarbij de spelers de stappen van de onderstaande\ntechnieken, op de plaats/ in voorwaartse richting moeten\nuitvoeren. De speler heeft daarbij een bal in de handen die hij, op\neen teken van de trainer, in verschillende standen langs zijn\nlichaam moet brengen..\n1. Tripling (Stap 1, 2, 3 en 4)\n2. Skipping ( Stap 1, 2, 3 en 4)\n3. Hielaanslag (Stap 1 en 2)\nOpgelet!\nDeze oefening kan ook uitgevoerd worden als aanleervorm.\nDoor de bal in verschillende posities te houden wordt er veel\ngevraagd van de rompstabiliteit van de speler. (Rompstabiliteit:\nhet stilhouden van het bovenlichaam.)\nMaterialen\nAantal spelers: 15\nAantal pylonen: 0\nAantal ballen: 15\nOrganisatie:\nDe spelers staan kris kras door elkaar in het 16-\nmeter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n2 TEGEN 1\nMethodiek\nIn ieder vak van 3 aaneengeschakelde vakken staat een speler.\nDe speler in het middelste vak is de lummel.\nDe spelers in de buitenste vakken proberen de bal over te spelen\ndoor het middelste vak heen, zonder dat de lummel de bal\nonderschept.\nAls de lummel de bal onderschept moet de speler die de bal als\nlaatste aanraakte / speelde wisselen met de lummel.\nAls de bal buiten de buitenste vakken komt, wordt de speler die\nals laatste de bal raakte de lummel.\nVariatie:\n- per X-aantal keer overspelen krijgen de ''''balbezitters'' een punt\n- de bal moet in beweging blijven, dus de balbezitters mogen niet\nstil gaan staan met de bal.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: 3-tal 1 bal\nAantal pylonen: 8\nAfstand pylonen: 8 bij 8 meter\nAanwijzingen\nSpelers coachen op:\n- Schieten met de binnenkant van de voet.\n- Speelbeen loodrecht op de speelrichting.\n- Voetzool parallel met de grond."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Schaar (Stap 3)\n- Akka (buiten-binnen) (Stap 1)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 2: Het aanleren van de techniek Akka (buiten-binnen)\n(Stap 2). Het oefenen van de techniek Schaar (Stap 4).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n(4 : 1) OEFENING 1\nMethodiek\nVier aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\n3x bal afnemen is wisselen van taak met de aanvaller die het\nlangst niet in het midden heeft gestaan.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 5\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 4 spelers nemen positie in op de 4 zijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de vier\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "techniek", "title": "LIJNDRIBBEL 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna de bal over de lijn aan de\noverkant van het vak te dribbelen.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nDe aanvallers mogen hierbij geen buitenspel lopen. De\nbuitenspellijn wordt bepaald door de laatste verdediger (Alleen\nvan toepassing voor teams 11-11).\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 8\nAantal ballen: 3\nAantal pylonen: 8\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling."}], "session_b": [{"type": "warming_up", "title": "TWEETAL TIKKERTJE", "content": "Twee spelers vormen een tweetal door de hand van elkaar vast te houden. Met\nde vrije hand mogen ze andere spelers proberen te tikken. Een getikte speler\nsluit bij het tweetal aan. Bij 4 spelers wordt het viertal weer opgesplitst in twee\ntweetallen.\nWie blijft er over?\nOpgelet!\nHoudt de handen stevig vast.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 8 of meer spelers\nPylonen: 4 om het speelveld af te bakenen."}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ZELFDE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 1: Aanbieden voorwaarts en achterwaarts\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Schaar (Stap 3)\n- Akka (buiten-binnen) (Stap 1)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 4) en\nAkka (buiten-binnen) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nLIJNDRIBBEL 2:1 ZONDER DOEL\nMethodiek\nd.w.z. dat 2 aanvallers d.m.v. samenspel/ een persoonlijke actie\neen verdediger uitspelen, om daarna te scoren door de bal over\nde lijn te dribbelen.\nOpgelet!\nDe 2 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nMet de afgepakte bal eerst het recht van aanval halen door de bal\nterug te spelen naar de tweede man.\nBij de verdedigende partij gaat er direct één speler het veld uit.\nMaterialen\nAantal spelers: 4 (3+1)\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 15m bij 10m\nE-pupillen: 18m bij 12m\nD-pupillen: 20m bij 15m\nC-,B-,A-junioren: 25m bij 20m\nOrganisatie:\nHet spel wordt gespeeld met 3 spelers in het\nveld en één speler (verdediger)daarbuiten. Bij\neen afgepakte bal moet, voordat het spel hervat\nkan worden, eerst het recht van aanval ( d.w.z.\ner wordt gewisseld van taak/ speler) gehaald\nworden.\nAanwijzingen\nAanvallers coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- keuzes maken aan de bal( 1:1 of overspelen)\n- rekening houden, bij het innemen van een\naanvallende positie, met de omschakeling bij\nbalverlies(restverdediging)\nVerdediger coachen op:\n- rekening houden met een goed zicht op de\npositie van de beide aanvallers bij het\ninnemen van een verdedigende positie(open\nstaan)\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O9', 4, '{"session_a": [{"type": "warming_up", "title": "KNIEHEF TIKKERTJE / HAKKEN-BIL TIKKERTJE", "content": "Dit is een oefening, waarbij de speler(s) de stap van één van de onderstaande\ntechnieken uitvoeren in de vorm van een tikspel. Eén speler moet, als tikker, de\nandere spelers proberen te tikken, terwijl zij (tikker en overige spelers) tijdens\nhet lopen één van de onderstaande technieken verwerken in hun looptechniek.\n1. Skipping (Stap 4)\n2. Hielaanslag (Stap 2)\nTerug komen tijdens het tikspel:\n- hierbij wordt gewerkt vanuit het principe “3 is te veel”.Dat wil zeggen dat\ntelkens als er een derde speler bij de 2 langs de kant staande afgetikte spelers\naansluit, de eerste afgetikte speler weer mee gaat doen aan het spel.\nDifferentiatie:\n- bij dit spel kan je het aantal tikkers variëren.\nOpgelet!\n- dit zijn introductievormen voor de looptraining.\nMaterialen\nAantal spelers: 15\nOrganisatie:\n- de afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Aai-buitenkantvoet (Stap 2+3)\n- Akka (binnen-voor) (Stap 1)\n- Sleep (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 1: Het aanleren van de techniek Aai buitenkant voet (Stap\n4).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.3 A: VOOR POSITIESPELEN (3:0)", "content": "Bij deze oefening is het belangrijk dat de speler in balbezit 2\nspeelmogelijkheden heeft.\nDe aanbiedende spelers moeten, om aanspeelbaar te kunnen zijn,\naan beide zijden vrijkomen.\nDeze spelers kunnen hierbij de bal op de volgende manier\nverwerken:\n- Links aannemen en links doorspelen\n- Links aannemen en rechts doorspelen\n- Rechts aannemen en rechts doorspelen\n- Rechts aannemen en links doorspelen.\nDe spelers hebben dan de volgende afspeelmogelijkheden:\n- Speler 1 kan op 2 en 3 spelen\n- Speler 2 kan op 1 en 3 spelen\n- Speler 3 kan op 1 en 2 spelen\nVariatie in uitvoering:\n- Inspelen met de klok mee\n- Inspelen tegen de klok in\n- Spelen op eigen intuïtie\n- Verhogen van speelsnelheid\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nmedespeler.\nAannemen:\n- Voor je liggen maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aanname, zodat de bal twee kanten\nopgespeeld kan worden."}, {"type": "techniek", "title": "DERDE MAN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: 4-6\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}], "session_b": [{"type": "warming_up", "title": "PAPEGAAIEN", "content": "Elk tweetal heeft één bal. Eén speler, zonder bal, loopt voorop en\nbepaald de koers door het vak. De andere speler, met bal,\nprobeert hem overal te volgen.\nOpgelet!\nBewaak de onderlinge afstand van circa 2 mtr.\nMaterialen\nTijd: 10-15 min\nRonde tijden: 1 a 2 min\nPylonen: 4 pylonen om het speelveld uit te zetten\nBallen: per tweetal een bal\nAanwijzingen\n- Maak makkelijke loopacties en maak het\nlater moeilijker\n- Maak het speelveld groter/ kleiner om het\nvoor de spelers makkelijker/ moeilijker te\nmaken.\n- Een kleiner speelveld is moeilijker omdat de\nspelers dichter op elkaar lopen."}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ANDERE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nlinkervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been aannemen en met andere\nbeen spelen.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 1: Aanbieden voorwaarts en achterwaarts\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2 A: DRIBBELEN (LIJN/STROOMVORM, HEEN/TERUG)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2.\n- Speler 1 loopt achter de bal aan naar speler 3 en sluit achter\nhem aan.\nB. Speler 2 dribbelt naar speler 1.\n- Speler 2 neemt de bal met rechts aan en dribbelt de bal, met de\nbuitenkant van de rechtervoet, terug.\n- Speler 2 neemt de plaats in van speler 1, etc.\nVariatie in uitvoering:\n- met links aannemen en dribbelen.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAannemen van de bal:\n- snelheid houden na de aanname voor de\nvolgende actie.\nDribbelen van de bal:\n- speelbeen: Bal steeds zodanig en zo vaak\nraken dat hij in het looptempo en in goede\nrichting kan worden meegenomen \"bal aan\nelastiekje\".\n- raakvlak: Het beroeren van de bal\nafwisselend met wreef, binnen- en buitenkant\nvan de voet afhankelijk van\nrichtingsverandering.\n- over de bal heen kijken.\n(3 : 1) OEFENING 1\nMethodiek\nREGELS:\n• Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• 3x bal afnemen is wisselen van taak met de aanvaller die het\nlangst niet in het midden heeft gestaan.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 4\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nORGANISATIE:\n• De 3 spelers nemen positie in op 3 van de 4\nzijden.\n• De verdediger neemt de positie in het midden\nin\n• De bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het goed aanspeelbaar zijn aan beide\nzijden van de speler in balbezit.\n• het goed vragen om de bal aan de kant van\nde bal.\n• het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n• het zoveel mogelijk over de bal heen kijken.\nVERDEDIGER COACHEN OP:\n• Druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O9', 5, '{"session_a": [{"type": "warming_up", "title": "OMSCHAKELINGSTIKKERTJE", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nOp een teken van de trainer probeert de speler uit de ene groep de andere\nspeler van het tweetal uit de andere groep te tikken.\nNadat hij hem getikt heeft draait hij direct van hem weg en versnelt naar de\nzijlijn. De andere speler probeert op zijn beurt de eerste speler, nog voordat hij\nde zijlijn heeft gepasseerd, te tikken.\nDifferentiatie gemakkelijk:\n- het spel “koe-kopen”.\nDifferentiatie moeilijk:\n- er kan gevarieerd worden door spelers met een bal aan de zijlijn te laten staan,\nom een kaats aan te gaan met de weggedraaide speler. Hij komt hierbij als het\nware in de bal. Omschakeling met bal (1)\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- de afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "STAP 1:VAKKENKONINGEN (3)", "content": "Twee spelers staan tegenover elkaar binnen een lang vak en\nproberen de onderstaande opdrachten uit te voeren zonder dat de\nbal buiten het vak komt.\nProbeer met een van de onderstaande opdrachten, overspelend\nnaar de overkant te komen zonder dat de bal buiten het vak komt.\nHierbij loopt een speler naar links en de andere naar rechts.\n-wie haalt de overkant en terug zonder fouten of wie zijn het\neerste heen en terug?\nDe opdrachten zijn als volgt:\n- speel de bal met de voet waarmee je aanneemt terug\n- speel de bal met de andere voet terug als waarmee je aanneemt\n- speel de bal direct terug met de voet waar je de bal op krijgt.\nOpgelet!\n- spreek in kindertaal\n- speel de bal terug met de voet waarmee je aanneemt of speel\nde bal terug met de andere voet of speel de bal direct terug met\nde voet waar je de bal op krijgt.\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 2\nAfstand van pylonen:1e en 2e jaars F-pupillen:\n2/3 m.\nAanwijzingen\nAannemen:\n- bal moet binnen je bereik voor je liggen\n- houd na de aanname snelheid voor de\nvolgende actie.\nSpelen binnenkant voet:\n- speel de bal met de juiste snelheid en op\nhet goede been aan\n- speel de bal strak en met gevoel in\n- laat het schietbeen doozwaaien\n- raak de bal in het hart\n- houd spanning in de voet.\nB. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM\nMethodiek\nSpelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Aai-buitenkantvoet (Stap 2+3)\n- Akka (binnen-voor) (Stap 1)\n- Sleep (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 2: Het aanleren van de techniek Sleep (Stap 3). Het\noefenen van de techniek Aai buitenkant voet (Stap 4).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "LIJNDRIBBEL 2:1 MET DOEL", "content": "d.w.z. dat 2 aanvallers d.m.v. samenspel/ een persoonlijke actie\neen verdediger uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 2 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdediger kan de afgepakte bal scoren door de bal over de\nlijn aan de overkant te dribbelen.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 15m bij 10m\nE-pupillen: 18m bij 12m\nD-pupillen: 20m bij 15m\nC-,B-,A-junioren: 25m bij 20m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- keuzes maken aan de bal( 1:1 of overspelen)\n- rekening houden, bij het innemen van een\naanvallende positie, met de omschakeling bij\nbalverlies(restverdediging)\nVerdediger coachen op:\n- rekening houden met een goed zicht op de\npositie van de beide aanvallers bij het\ninnemen van een verdedigende positie(open\nstaan)\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "RATTEN EN RAVEN MET BAL", "content": "Het spel wordt gespeeld met tweetallen, die recht tegenover\nelkaar staan op een onderlinge afstand van 2 meter. Elke speler\nheeft een bal.\nAan de ene kant staan de ratten en aan andere kant de raven.\nAls verteller vertelt de trainer een verhaal waarin de woorden\nratten en raven steeds voorkomen. Op het moment dat de trainer\neen van deze namen noemt, dan moet die groep zo snel mogelijk\nnaar hun achterlijn zien te lopen.De andere groep moet hen zien\nte tikken voordat zij bij hun achterlijn zijn.\nJe krijgt voor elke getikte speler 1 punt.\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nVoor iedere speler een bal\nPylonen:\n- 4 om het speelveld af te bakenen.\n- 4 pylonen/hoedjes om de vrije zone aan te\ngeven.\n- 4 pylonen/hoedjes om de startlijn aan te geven.\n- 2 pylonen/hoedjes op de middenlijn aan te\ngeven\nAanwijzingen\n- zorg dat de spelers ook echt starten\nwanneer hun naam genoemd wordt\n- probeer een leuk verhaal van te maken.\nNiet alleen maar ratten en raven roepen.\nA. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM\nMethodiek\nSpelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Schaar (Stap 3)\n- Akka (buiten-binnen) (Stap 1)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 4) en\nAkka (buiten-binnen) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ZELFDE/ANDERE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met dezelfde voet.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 1: Aanbieden voorwaarts en achterwaarts\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 45º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: 4-6\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O9', 6, '{"session_a": [{"type": "warming_up", "title": "SPIEGELEN (1)", "content": "Oefeningen, waarbij de speler(s) de door de tegenstander uitgevoerde stappen\nvan de onderstaande technieken, op de plaats, nadoet(n).\n1. Trippling (Stap 1, 2)\n2. Skipping (Stap 1, 2, 3)\n3. Hielaanslag ( Stap 1)\nOpgelet!\n- alleen uitvoeren als de spelers bekend zijn met bovenstaande technieken.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nDe pylonen vormen een rechte lijn van 2 mtr.\nOrganisatie:\n- de spelers staan hierbij recht tegenover één speler die de leiding heeft. Zij\nmoeten daarbij zijn bewegingen volgen (spiegelen)."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Aai-buitenkantvoet (Stap 2+3)\n- Akka (binnen-voor) (Stap 1)\n- Sleep (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het aanleren van de techniek Akka (binnen-voor) (Stap\n2). Het oefenen van de techniek Aai buitenkant voet (Stap 4) en\nSleep (Stap 3).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSTAP 2.2 A: AANBIEDEN, HEEN/TERUG IN LIJNVORM COMBINATIE\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 speelt de bal met de binnenkant van de linker-\n/rechtervoet.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 2 kaatst de bal met de binnenkant van de linker-\n/rechtervoet terug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 kaatst de bal met de binnenkant van de linker-\n/rechtervoet.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(3 : 1) OEFENING 1", "content": "REGELS:\n• Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• 3x bal afnemen is wisselen van taak met de aanvaller die het\nlangst niet in het midden heeft gestaan.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 4\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nORGANISATIE:\n• De 3 spelers nemen positie in op 3 van de 4\nzijden.\n• De verdediger neemt de positie in het midden\nin\n• De bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het goed aanspeelbaar zijn aan beide\nzijden van de speler in balbezit.\n• het goed vragen om de bal aan de kant van\nde bal.\n• het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n• het zoveel mogelijk over de bal heen kijken.\nVERDEDIGER COACHEN OP:\n• Druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}], "session_b": [{"type": "warming_up", "title": "BLESSURE TIKKERTJE", "content": "Eén speler probeert andere spelers te tikken. De getikte speler\nwordt de nieuwe tikker, maar moet met één hand de getikte plek\nvasthouden, terwijl hij met de andere hand moet proberen een\nandere speler te tikken.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 8 of meer spelers\nPylonen: 4 om het speelveld af te bakenen.\nAanwijzingen\n- Let goed op de plek waar de speler getikt\nwordt.\nSTAP 2.4 A: VOOR POSITIE-PARTIJSPELEN (2:0)\nMethodiek\nBeide spelers staan voorwaarts gericht.\nA. Speler 1 start de oefening door de bal naar speler 2 te spelen.\nB. Speler 2 dribbelt de bal voorwaarts.\nC. Speler 2 speelt de bal vervolgens weer terug naar speler 1.\nD. Idem.\nOpgelet!\nBelangrijk hierbij is dat de spelers de aannames afwisselen door:\nDe ene keer de bal kort bij het standbeen aan te nemen en de\nandere keer voorbij het standbeen of door een beweging extra te\nmaken en de bal vooruit mee te nemen en dan weer terug.\nVariatie in uitvoering:\nIdem in tegengestelde richting met het andere been.\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 15 bij 10m\nE-pupillen: 18 bij 12m\nD-pupillen: 20 bij 15m\nC-,B-,A-junioren: 25 bij 20m\nAanwijzingen\nAanbieden:\n- Na de aanname van de medespeler om de\nbal vragen.\nAannemen:\n- Voor je, binnen je bereik.\n- Na de aanname snelheid houden voor de\nvolgende actie.\n- Naar voren gerichte open aanname.\n- Bal vlakbij of voorbij het standbeen\naannemen."}, {"type": "techniek", "title": "STAP 1: PARCOURS DRIBBELEN", "content": "De spelers slalommen dribbelend het hele parcours door.\nVariatie in aanbieden:\n- varieer in uitvoeringssnelheid\n- varieer onderlinge afstand pylonen\n- voer de oefening in wedstrijdvorm uit.\nVariatie\nVariatie 4: Parcours dribbelen met zowel rechter als linker voet.\nMaterialen\nAantal spelers: 4-10\nAantal ballen: elke speler 1 bal\nAantal pylonen: 8\nOnderlinge afstand pylonen: 2 a 3 meter\nAanwijzingen\nSpelers coachen op:\n- houd de bal dichtbij je, maar niet onder je\n- probeer de bal zoveel mogelijk te raken\n- probeer de bal bij iedere stap te raken, dan\nkun je de bal ook beter sturen.\nPARCOURS DRIBBELEN EN AFWERKEN\nMethodiek\nDe spelers slalommen dribbelend het hele parcours door en werk\naf op doel.\nVariatie in aanbieden:\n- Varieer in uitvoeringssnelheid\n- Varieer onderlinge afstand pylonen.\n- Voer de oefening in wedstrijdvorm uit.\nVariatie\nVariatie 4: Parcours dribbelen met rechter en linker voet.\nMaterialen\nAantal spelers: 4-10\nAantal ballen: elke speler 1 bal\nAantal pylonen: 8\nDoelen: 2\nOnderlinge afstand pylonen: 2 a 3 meter\nAanwijzingen\nSpelers coachen op:\n- Houdt de bal dichtbij je, maar niet onder je.\n- Probeer de bal zoveel mogelijk te raken.\n- Probeer de bal bij iedere stap te raken, dan\nkun je de bal ook beter sturen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O9', 7, '{"session_a": [{"type": "warming_up", "title": "HIELAANSLAG-ESTAFETTE", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek in voorwaartse richting uitvoert(en) tot bij de medespeler\naan de andere kant. Ondertussen voert hij daarbij de hielslag uit,\nterwijl hij de bal met een lichte hoek in de ellebogen in de handen\nvoor het lichaam houdt. Aan de overkant gekomen geeft hij de bal\nover en zijn medespeler voert vervolgens ook de oefening in\ntegengestelde richting uit.\n1. Hielaanslag (Stap 2)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler stap 2 van de hielaanslag beheerst.\nMaterialen\nAantal spelers: 10\nAantal ballen: 2\nAantal pylonen: 4\nOrganisatie:\nDe spelers( 3 aan de ene en 2 aan de andere\nkant) staan verdeeld in 2 rijen achter de op een\nonderlinge afstand van 15 mtr. geplaatste\npylonen tegenover elkaar.De voorste speler\nheeft een bal in de handen en start de oefening\nWinnaar is de rij die het eerst de oefening\nuitgevoerd heeft\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n2 TEGEN 1\nMethodiek\nIn ieder vak van 3 aaneengeschakelde vakken staat een speler.\nDe speler in het middelste vak is de lummel.\nDe spelers in de buitenste vakken proberen de bal over te spelen\ndoor het middelste vak heen, zonder dat de lummel de bal\nonderschept.\nAls de lummel de bal onderschept moet de speler die de bal als\nlaatste aanraakte / speelde wisselen met de lummel.\nAls de bal buiten de buitenste vakken komt, wordt de speler die\nals laatste de bal raakte de lummel.\nVariatie:\n- per X-aantal keer overspelen krijgen de ''''balbezitters'' een punt\n- de bal moet in beweging blijven, dus de balbezitters mogen niet\nstil gaan staan met de bal.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: 3-tal 1 bal\nAantal pylonen: 8\nAfstand pylonen: 8 bij 8 meter\nAanwijzingen\nSpelers coachen op:\n- Schieten met de binnenkant van de voet.\n- Speelbeen loodrecht op de speelrichting.\n- Voetzool parallel met de grond."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Aai-buitenkantvoet (Stap 2+3)\n- Akka (binnen-voor) (Stap 1)\n- Sleep (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 4), Sleep (Stap 3) en Akka (binnen-voor) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nIN SPELVORM MET DRIBBEL\nMethodiek\nDit spel wordt uitgevoerd met tweetallen.\nA. De spelers 1 dribbelen de bal naar het midden en schieten de\nbal op het doeltje van speler 2.\nB. de spelers 2 proberen de bal uit het doel te houden.\nNa 5x schieten wisselen de spelers 1 en 2 van plek, dus dan gaat\nspeler 1 op goal en speler 2 gaat afwerken.\nVariatie in uitvoering:\n- Vervang de pylonen door echte doeltjes van 3 bij 1 mtr.\n- Idem met het andere been.\nMaterialen\nAantal spelers: 8-12\nAantal ballen: 4-6\nAantal pylonen: 15-21\nStartafstand: 10 meter vanaf doel\nSchietafstand: 5 meter vanaf doel\nDoordraaien:\nna 5x schieten wordt er gewisseld van plek,\nspelers 1 worden keeper en spelers 2 worden\nafwerkers.\nAanwijzingen\nSpelers coachen op:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang van de dribbel naar het\nschieten moet vloeiend verlopen."}, {"type": "techniek", "title": "LIJNDRIBBEL 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna de bal over de lijn aan de\noverkant van het vak te dribbelen.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nDe aanvallers mogen hierbij geen buitenspel lopen. De\nbuitenspellijn wordt bepaald door de laatste verdediger (Alleen\nvan toepassing voor teams 11-11).\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 8\nAantal ballen: 3\nAantal pylonen: 8\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling."}], "session_b": [{"type": "warming_up", "title": "CLUBS / LANDENSPEL", "content": "Elke speler heeft een bal en dribbelt in het rond.\nIn de hoeken van het veld zijn vierkanten, die de namen dragen\nvan een voetbalclub of een land.\nBij het noemen van de naam van de club of het land moeten de\nspelers zo snel mogelijk naar het desbetreffende vak dribbelen en\ndaar met de voet op de bal blijven staan.\nDe laatst aangekomen speler krijgt een strafpunt.\nWinnaar is degene met de minste strafpunten.\nVariatie in aanbieden:\n- Met Kerst, Pasen of Sinterklaas gebruik je deze themagerichte\nnamen.\n- Spelers moeten de bal stoppen door b.v. op de bal te gaan zitten\nof iets anders te doen.\nMaterialen\nAantal spelers: 4-10\nAantal ballen: elke speler 1 bal\nAantal pylonen: 16\nVeldafmeting: 20 bij 20 meter (incl. hoekvakken\nvan 4 bij 4 meter)\nAanwijzingen\nSpelers coachen op:\n- De bal dichtbij je houden.\n- Probeer de bal zoveel mogelijk aan te raken.\n- Probeer bij iedere stap de bal een keer aan\nte raken.\n- Door het vele bal contact kunnen spelers\ngemakkelijker de bal sturen.\n- De bal moet onder de voet gestopt worden"}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ZELFDE/ANDERE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met dezelfde voet.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 1: Aanbieden voorwaarts en achterwaarts\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Schaar (Stap 3)\n- Akka (buiten-binnen) (Stap 1)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 4) en\nAkka (buiten-binnen) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n(3 : 1) OEFENING 1\nMethodiek\nREGELS:\n• Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• 3x bal afnemen is wisselen van taak met de aanvaller die het\nlangst niet in het midden heeft gestaan.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 4\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nORGANISATIE:\n• De 3 spelers nemen positie in op 3 van de 4\nzijden.\n• De verdediger neemt de positie in het midden\nin\n• De bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het goed aanspeelbaar zijn aan beide\nzijden van de speler in balbezit.\n• het goed vragen om de bal aan de kant van\nde bal.\n• het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n• het zoveel mogelijk over de bal heen kijken.\nVERDEDIGER COACHEN OP:\n• Druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O9', 8, '{"session_a": [{"type": "test", "title": "SPEEDLADDER (1)", "content": "Is een oefening, waarbij de voorwaartse vormen worden\naangeleerd in de speedladder. De oefening is opgebouwd van\ngrove motoriek naar de fijne motoriek. Dat wil zeggen binnen de\nlooptraining, er wordt gewerkt van een skipping naar skipping 45\ngraden en vervolgens naar kort voetenwerk.\nStap 1: Eén voetje in het raam plaatsen.\nStap 2: Twee voetjes in het raam plaatsen.\nStap 3: Drie voetjes in het raam plaatsen.\nDifferentiatie:\nStroop de ladder op, zodat er door de spelers ten alle tijden een\nskipping ingezet moet worden.\nLet op!\nDeze vormen kunnen spelenderwijs worden aangeleerd.\nMaterialen\nAantal spelers: het gehele team.\nAantal speedladders:\nEén, bij voorkeur twee.\nAantal pylonnen:\nEén\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast.\n2 TEGEN 1\nMethodiek\nIn ieder vak van 3 aaneengeschakelde vakken staat een speler.\nDe speler in het middelste vak is de lummel.\nDe spelers in de buitenste vakken proberen de bal over te spelen\ndoor het middelste vak heen, zonder dat de lummel de bal\nonderschept.\nAls de lummel de bal onderschept moet de speler die de bal als\nlaatste aanraakte / speelde wisselen met de lummel.\nAls de bal buiten de buitenste vakken komt, wordt de speler die\nals laatste de bal raakte de lummel.\nVariatie:\n- per X-aantal keer overspelen krijgen de ''''balbezitters'' een punt\n- de bal moet in beweging blijven, dus de balbezitters mogen niet\nstil gaan staan met de bal.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: 3-tal 1 bal\nAantal pylonen: 8\nAfstand pylonen: 8 bij 8 meter\nAanwijzingen\nSpelers coachen op:\n- Schieten met de binnenkant van de voet.\n- Speelbeen loodrecht op de speelrichting.\n- Voetzool parallel met de grond."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Aai-buitenkantvoet (Stap 2+3)\n- Akka (binnen-voor) (Stap 1)\n- Sleep (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 4), Sleep (Stap 3) en Akka (binnen-voor) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nLIJNDRIBBEL 2:1 MET DOEL\nMethodiek\nd.w.z. dat 2 aanvallers d.m.v. samenspel/ een persoonlijke actie\neen verdediger uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 2 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdediger kan de afgepakte bal scoren door de bal over de\nlijn aan de overkant te dribbelen.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 15m bij 10m\nE-pupillen: 18m bij 12m\nD-pupillen: 20m bij 15m\nC-,B-,A-junioren: 25m bij 20m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- keuzes maken aan de bal( 1:1 of overspelen)\n- rekening houden, bij het innemen van een\naanvallende positie, met de omschakeling bij\nbalverlies(restverdediging)\nVerdediger coachen op:\n- rekening houden met een goed zicht op de\npositie van de beide aanvallers bij het\ninnemen van een verdedigende positie(open\nstaan)\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}], "session_b": [{"type": "warming_up", "title": "GEWOON TIKKERTJE", "content": "Elke speler heeft een bal aan zijn voet, behalve de tikker. De\ntikker probeert zo veel mogelijk spelers te tikken.\nVariatie:\n- De tikker heeft ook een bal.\n- De tikker kan spelers aftikken door hun bal weg te schoppen\nOpgelet!\nJe mag weer deelnemen als een \"vrije speler\" je weer \"vrij\" getikt\nheeft.\nMaterialen\nDuur spel:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 6-8 of meer spelers\nPylonen: 4 om het speelveld af te bakenen.\nBallen: voor iedere speler een bal\nAanwijzingen\nWedstrijdopties:\nOptie 1: Tel het aantal getikte spelers.\nOptie 2: De getikte speler gaat aan de kant\nstaan.\nOptie 3: De getikte speler wordt de nieuwe\ntikker.\nSTAP 1: ONDERSCHEPPEN\nMethodiek\nTweetallen, elk tweetal met één bal, staan tegenover elkaar met\nin het midden een verdediger.\nDe tweetallen passen de bal naar elkaar en de verdediger\nprobeert de bal te onderscheppen.\n- wisselen van verdediger bij 3 onderscheppingen.\nVariatie:\n- verhogen van het aantal onderscheppingen\n- gebruik van meerdere verdedigers.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: elke speler 1bal\nAantal pylonen: 4\nAfstand pylonen: 15 bij 25 meter\nAanwijzingen\nSpelers coachen op:\n- schieten met de binnenkant van de voet\n- speelbeen loodrecht op de speelrichting\n- voetzool parallel met de grond."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Schaar (Stap 3)\n- Akka (buiten-binnen) (Stap 1)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 4) en\nAkka (buiten-binnen) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "IN STROOMVORM (1)", "content": "Deze oefenvorm wordt uitgevoerd met twee rijen spelers.\nA. De spelers 1 dribbelen de bal naar de eerste pylon.\nB. Ter hoogte daarvan passen de spelers 1 de bal op de kaatser\nen lopen daarna door om de bal in de loop terug te krijgen.\nC. Vervolgens schieten de spelers 1 de bal met de\nbinnenkant/wreef van de rechtervoet op doel.\nOpgelet!\nDe volgende speler start pas nadat er op doel geschoten is.\nDe spelers moeten de bal in één keer schieten en vooral niet stil\ngaan staan om te schieten.\nVariatie in uitvoering:\n- Idem andersom met het andere been.\n- Vergroot/verklein de afstand ten opzichte van het schietpunt en/\nof het vak.\nMaterialen\nAantal spelers: 8- 12\nAantal pylonen: 8\nAantal ballen: 8-12\nBreedte speelveld: 20m\nDoelen: 2\nF-,E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen:\nStartafstand vanaf doel:\n2e jaars F-pupillen: 11 m\n1e jaars E-pupillen: 13 m\n2e jaars E-pupillen: 15 m\nD-pupillen: 17 m\nC-,B-,A-junioren: >19 m\nAfstand kaatser vanaf doel:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- De spelers staan in twee groepen verdeeld ter\nhoogte van het ene doel en tegenover het\nandere doel.\n- Nadat de speler geschoten heeft, haalt hij zijn\neigen bal op en sluit achter in de andere rij aan.\nAanwijzingen\nSpelers coachen op:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O9', 9, '{"session_a": [{"type": "warming_up", "title": "DE OOIEVAAR", "content": "Is een oefening, waarbij de speler(s) de stap van één van de\nonderstaande technieken, op de plaats, moet(en)uitvoeren.\nBelangrijk hierbij is dat de speler na 5 skippings gedurende 5 tot\n10 seconden op zijn gehele voet stil blijft staan. Als de speler dit\nniet volhoud dan moet hij een sprint maken tot aan de 16-\nmeterlijn of tot bij de trainer.\n1. Skipping (Stap 3)\n2. Hielaanslag ( Stap 1)\nOpgelet!\nDit is een aanleervorm, waarbij de speler de stabiliteit in zijn been\n(knie/enkel), maar ook dat van zijn bovenlichaam (heup/borst)\nleert te beheersen.\nDifferentiatie:\n- Op de bal van de voet stilstaan\n- Uitvoering in voorwaartse richting.\n- Variëren in aantal skippings.\nMaterialen\nAantal spelers: gehele team\nOrganisatie:\nDe spelers staan kris kras door elkaar in het 16-\nmeter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 A: AANBIEDEN, HEEN/TERUG (ZELFDE/ANDERE BEEN) IN LIJNVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"voorwaarts\" aan.\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- speler 2 neemt de bal met de binnenkant van de linkervoet aan.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich \"voorwaarts\" aan.\n- speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- speler 1 neemt de bal met de binnenkant van de linkervoet aan,\netc.\nVariatie in uitvoering:\n- idem, maar nu aannemen en spelen met dezelfde voet\nVariatie in aanbieden:\n- achterwaarts\n- naar rechts\n- naar links\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 2\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAannemen:\n- bal moet voor je liggen, maar binnen bereik.\n- snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet.\nSTAP 2 C: DRIBBELEN (PLUSVORM, TOT 90º)\nMethodiek\nA. Speler 1 speelt naar speler 2.\n- speler 1 speelt de bal op de \"naar links\" aanbiedende speler 2\n- speler 1 loopt achter de bal aan naar de plaats van speler 2.\nB. Speler 2 dribbelt naar volgende pylon.\n- speler 2 neemt de bal \"naar links\" opengedraaid met links aan\nen dribbelt de bal, met de buitenkant van de linkervoet, naar de\nvolgende pylon.\nC. Speler 2 speelt naar speler 1.\n- speler 2 speelt de bal op de \"naar rechts\" aanbiedende speler 1,\netc.\nIdem, voor spelers 3 en 4; 5 en 6; 7 en 8.\nVariatie in aanbieden:\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 8\nAantal ballen: 4\nAantal pylonen: 4\nAfstand tussen pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende\npylon.\nAanwijzingen\nAannemen van de bal:\n- open aanname, gericht naar voren.\n- snelheid houden na de aanname voor de\nvolgende actie.\nDribbelen van de bal:\n- speelbeen: Bal steeds zodanig en zo vaak\nraken dat hij in het looptempo en in goede\nrichting kan worden meegenomen \"bal aan\nelastiekje\".\n- raakvlak: Het beroeren van de bal\nafwisselend met wreef, binnen- en buitenkant\nvan de voet afhankelijk van\nrichtingsverandering.\n- over de bal heen kijken."}, {"type": "techniek", "title": "(3 : 1) OEFENING 2", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden (omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 3 spelers nemen positie in op 3 van de 4\nzijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "TRANSFER SPEL", "content": "Het spel wordt gespeeld met (afhankelijk van de groepsgrootte) 5\nspelers en 6 trainers. De 5 spelers staan in een rij op een\narmlengte afstand tegenover 5 trainers aan één kant van het vak.\nDe overgebleven trainer staat tegenover de groep aan de andere\nkant van het vak. Hij heeft de beste faciliteiten en wil graag\nzoveel mogelijk spelers halen.\nDoor de naam van een speler te roepen probeert hij een speler af\nte pakken.\nDe speler reageert direct en probeert eerder dan zijn eigen trainer\nover de lijn bij de nieuwe trainer te komen.\nZij \"eigen trainer\" kan dit voorkomen door de speler te tikken\nvoordat hij over de lijn bij de andere trainer gaat.\nWelke trainer houd het langst zijn speler?\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 6-12 spelers\nPylonen: 4 om het speelveld af te bakenen.\nAanwijzingen\n- Spelers zijn vrij als ze over de lijn zijn en\nblijven in het vak staan.\n- Laat de trainers voldoende afstand houden\nten opzichte van de spelers\nSTAP 2.1 A: ZIJWAARTS AANBIEDEN, HEEN/TERUG IN LIJNVORM\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal met de binnenkant van de linkervoet aan.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich \"naar rechts aan\"\n- speler 2 speelt de bal met de binnenkant van de linkervoet\n- speler 1 neemt de bal met de binnenkant van de rechtervoet aan.\nC. Speler 1 speelt naar speler 2\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\nidem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 4\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2 A: DRIBBELEN (LIJN/STROOMVORM, HEEN/TERUG)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2.\n- Speler 1 loopt achter de bal aan naar speler 3 en sluit achter\nhem aan.\nB. Speler 2 dribbelt naar speler 1.\n- Speler 2 neemt de bal met rechts aan en dribbelt de bal, met de\nbuitenkant van de rechtervoet, terug.\n- Speler 2 neemt de plaats in van speler 1, etc.\nVariatie in uitvoering:\n- met links aannemen en dribbelen.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAannemen van de bal:\n- snelheid houden na de aanname voor de\nvolgende actie.\nDribbelen van de bal:\n- speelbeen: Bal steeds zodanig en zo vaak\nraken dat hij in het looptempo en in goede\nrichting kan worden meegenomen \"bal aan\nelastiekje\".\n- raakvlak: Het beroeren van de bal\nafwisselend met wreef, binnen- en buitenkant\nvan de voet afhankelijk van\nrichtingsverandering.\n- over de bal heen kijken.\nLIJNDRIBBEL 2:1 MET DOEL\nMethodiek\nd.w.z. dat 2 aanvallers d.m.v. samenspel/ een persoonlijke actie\neen verdediger uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 2 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdediger kan de afgepakte bal scoren door de bal over de\nlijn aan de overkant te dribbelen.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 15m bij 10m\nE-pupillen: 18m bij 12m\nD-pupillen: 20m bij 15m\nC-,B-,A-junioren: 25m bij 20m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- keuzes maken aan de bal( 1:1 of overspelen)\n- rekening houden, bij het innemen van een\naanvallende positie, met de omschakeling bij\nbalverlies(restverdediging)\nVerdediger coachen op:\n- rekening houden met een goed zicht op de\npositie van de beide aanvallers bij het\ninnemen van een verdedigende positie(open\nstaan)\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel."}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O9', 10, '{"session_a": [{"type": "warming_up", "title": "BALGOOCHELAAR", "content": "Oefeningen, waarbij de spelers de stappen van de onderstaande\ntechnieken, op de plaats/ in voorwaartse richting moeten\nuitvoeren. De speler heeft daarbij een bal in de handen die hij, op\neen teken van de trainer, in verschillende standen langs zijn\nlichaam moet brengen..\n1. Tripling (Stap 1, 2, 3 en 4)\n2. Skipping ( Stap 1, 2, 3 en 4)\n3. Hielaanslag (Stap 1 en 2)\nOpgelet!\nDeze oefening kan ook uitgevoerd worden als aanleervorm.\nDoor de bal in verschillende posities te houden wordt er veel\ngevraagd van de rompstabiliteit van de speler. (Rompstabiliteit:\nhet stilhouden van het bovenlichaam.)\nMaterialen\nAantal spelers: 15\nAantal pylonen: 0\nAantal ballen: 15\nOrganisatie:\nDe spelers staan kris kras door elkaar in het 16-\nmeter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSTAP 2.2 A: AANBIEDEN VOOR/ACHTERWAARTS, IN LIJNVORM\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"achterwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1, etc.\n- speler 1 biedt zich \"voorwaarts\" aan\n- speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"achterwaarts\" aan\n- speler 1 kaatst de bal met de binnenkant van de rechtervoet\nterug, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nAantal ballen: 1\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "C. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Uitstappen meenemen (Stap 3)\n- Akka (binnen-buiten) (Stap 1)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 1: Het aanleren van de techniek Uitstappen meenemen\n(Stap 4).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Akka (buiten-binnen) (Stap 3A)\n- Schaar (Stap 5A)\nDribbelen buitenkant voet, inzet beweging binnenkant voet:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\n- Uitstappen/meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna dribbelt hij, met de bal aan de voet, richting doel om\nvervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE -pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "GESPREIDE ORGANISATIE", "content": "Oefeningen, waarbij de stappen van de onderstaande technieken,\nop de plaats zonder elkaar te hinderen, verspreid over de hele\nrechthoek uitgevoerd moeten worden.\n- Schaar en Pirouette (Stap 1)\n- Uitstappen/meenemen (Stap 1)\n- De Overstap en De Verandering (Stap 1)\n- Kappen binnenkant voet (Stap 1)\n- De Schijntrap (Stap 1)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 4\nDe pylonen vormen een rechthoek van 10 bij 8\nmtr.\nOrganisatie:\nSpelers staan kris kras door elkaar.\nDe trainer geeft eerst een beeld van de oefening\nen controleert daarna de uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek zie\ntechnieklijst.\nSTAP 2.2 A: AANBIEDEN ZIJWAARTS, HEEN/TERUG IN LIJNVORM\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich \"naar rechts\" aan\n- speler 2 kaatst de bal met de binnenkant van de linkervoet terug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 kaatst de bal met de binnenkant van de rechtervoet\nterug, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 4\nAantal ballen: 1\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "STAP 2 C: DRIBBELEN (PLUSVORM, TOT 90º)", "content": "A. Speler 1 speelt naar speler 2.\n- speler 1 speelt de bal op de \"naar links\" aanbiedende speler 2\n- speler 1 loopt achter de bal aan naar de plaats van speler 2.\nB. Speler 2 dribbelt naar volgende pylon.\n- speler 2 neemt de bal \"naar links\" opengedraaid met links aan\nen dribbelt de bal, met de buitenkant van de linkervoet, naar de\nvolgende pylon.\nC. Speler 2 speelt naar speler 1.\n- speler 2 speelt de bal op de \"naar rechts\" aanbiedende speler 1,\netc.\nIdem, voor spelers 3 en 4; 5 en 6; 7 en 8.\nVariatie in aanbieden:\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 8\nAantal ballen: 4\nAantal pylonen: 4\nAfstand tussen pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAannemen van de bal:\n- open aanname, gericht naar voren.\n- snelheid houden na de aanname voor de\nvolgende actie.\nDribbelen van de bal:\n- speelbeen: Bal steeds zodanig en zo vaak\nraken dat hij in het looptempo en in goede\nrichting kan worden meegenomen \"bal aan\nelastiekje\".\n- raakvlak: Het beroeren van de bal\nafwisselend met wreef, binnen- en buitenkant\nvan de voet afhankelijk van\nrichtingsverandering.\n- over de bal heen kijken.\n(3 : 1) OEFENING 1\nMethodiek\nREGELS:\n• Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• 3x bal afnemen is wisselen van taak met de aanvaller die het\nlangst niet in het midden heeft gestaan.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 4\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nORGANISATIE:\n• De 3 spelers nemen positie in op 3 van de 4\nzijden.\n• De verdediger neemt de positie in het midden\nin\n• De bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het goed aanspeelbaar zijn aan beide\nzijden van de speler in balbezit.\n• het goed vragen om de bal aan de kant van\nde bal.\n• het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n• het zoveel mogelijk over de bal heen kijken.\nVERDEDIGER COACHEN OP:\n• Druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O9', 11, '{"session_a": [{"type": "warming_up", "title": "KNIEHEF TIKKERTJE / HAKKEN-BIL TIKKERTJE", "content": "Dit is een oefening, waarbij de speler(s) de stap van één van de onderstaande\ntechnieken uitvoeren in de vorm van een tikspel. Eén speler moet, als tikker, de\nandere spelers proberen te tikken, terwijl zij (tikker en overige spelers) tijdens\nhet lopen één van de onderstaande technieken verwerken in hun looptechniek.\n1. Skipping (Stap 4)\n2. Hielaanslag (Stap 2)\nTerug komen tijdens het tikspel:\n- hierbij wordt gewerkt vanuit het principe “3 is te veel”.Dat wil zeggen dat\ntelkens als er een derde speler bij de 2 langs de kant staande afgetikte spelers\naansluit, de eerste afgetikte speler weer mee gaat doen aan het spel.\nDifferentiatie:\n- bij dit spel kan je het aantal tikkers variëren.\nOpgelet!\n- dit zijn introductievormen voor de looptraining.\nMaterialen\nAantal spelers: 15\nOrganisatie:\n- de afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ZELFDE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "C. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Uitstappen meenemen (Stap 3)\n- Akka (binnen-buiten) (Stap 1)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 2: Het aanleren van de techniek Akka (binnen-buiten)\n(Stap 2). Het oefenen van de techniek Uitstappen meenemen\n(Stap 4).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "PAALTJES VOETBAL 2", "content": "Het spel wordt gespeeld met tweetallen, elk met 1 pylon en een\nbal. De ene speler is verdediger en de ander aanvaller. De\naanvaller moet proberen 1 punt te scoren door de pylon omver te\nschieten. De verdediger probeert dit te voorkomen.\nOpgelet!\n- Na een aantal minuten wisselen van functie.\n- De spelers moeten binnen het afgebakende veld blijven.\nVariatie:\nBij een score wisselen alle spelers tegelijk van functie\nMaterialen\nDuur:10-15 min\nAantal: 2 of meer spelers\nPylon: voor ieder tweetal 1\nBallen: 1-2\nAanwijzingen\nZorg dat de spelers niet voor de pylon blijven\nhangen.\nSTAP 1: POORTEN SPEL\nMethodiek\nElke speler heeft 1 bal en op een teken van de trainer proberen de\nspelers de bal door één van de drie poortjes naar de andere kant\nvan het veld te dribbelen. Onderweg proberen de \"balafpakkers \"\nde ballen van de spelers uit het vierkant te schieten.\n- bal kwijt, dan wordt je ook \"balafpakker\".\n- winnaar is de speler die overblijft.\nVariatie:\n- elke speler start met 3 punten. Bij balverlies gaat er telkens 1\npunt af.\n- bij 0 punten is de speler af.\n- winnaar is degene die over blijft.\nMaterialen\nAantal spelers: 6-8\nHoedjes: 6\nAantal ballen: elke speler 1 bal, behalve de\nbalafpakker\nHesjes: de balafpakker(s)\nAantal pylonen: 6\nAfstand tussen de pylonen: speelveld: ongeveer\n10 bij 15 meter\nAanwijzingen\nSpelers coachen op:\n- de bal dichtbij je houden\n- de bal goed afschermen\n- een andere kant opgaan als de tikker naar\nje toekomt\n- probeer snel de overkant te bereiken."}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ANDERE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nlinkervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been aannemen en met andere\nbeen spelen.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 45º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: 4-6\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "LIJNDRIBBEL 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna de bal over de lijn aan de\noverkant van het vak te dribbelen.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nDe aanvallers mogen hierbij geen buitenspel lopen. De\nbuitenspellijn wordt bepaald door de laatste verdediger (Alleen\nvan toepassing voor teams 11-11).\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 8\nAantal ballen: 3\nAantal pylonen: 8\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling."}]}'::jsonb),
('O9', 12, '{"session_a": [{"type": "warming_up", "title": "OMSCHAKELINGSTIKKERTJE", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nOp een teken van de trainer probeert de speler uit de ene groep de andere\nspeler van het tweetal uit de andere groep te tikken.\nNadat hij hem getikt heeft draait hij direct van hem weg en versnelt naar de\nzijlijn. De andere speler probeert op zijn beurt de eerste speler, nog voordat hij\nde zijlijn heeft gepasseerd, te tikken.\nDifferentiatie gemakkelijk:\n- het spel “koe-kopen”.\nDifferentiatie moeilijk:\n- er kan gevarieerd worden door spelers met een bal aan de zijlijn te laten staan,\nom een kaats aan te gaan met de weggedraaide speler. Hij komt hierbij als het\nware in de bal. Omschakeling met bal (1)\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- de afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ZELFDE/ANDERE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met dezelfde voet.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Aai-buitenkantvoet (Stap 2+3)\n- Akka (binnen-voor) (Stap 1)\n- Sleep (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 4), Sleep (Stap 3) en Akka (binnen-voor) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n(3 : 1) OEFENING 2\nMethodiek\nDrie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden (omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 3 spelers nemen positie in op 3 van de 4\nzijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "SIGNAALORGANISATIE (1)", "content": "Oefeningen, waarbij de stappen van de onderstaande technieken\ngekoppeld aan een nummer (1,2,3,4 etc.) of een naam, op of om\nde bal,uitgevoerd moeten worden.\n- Schaar en Pirouette (Stap 1)\n- Uitstappen/meenemen (Stap 1)\n- De Overstap en De Verandering (Stap 1)\n- Kappen binnenkant voet (Stap 1)\n- De Schijntrap (Stap 1)\nOpgelet!\n- alleen gebruiken als de spelers bekend zijn met de\nbovenstaande technieken.\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 4\nDe pylonen vormen een rechthoek van 10 bij 8\nmtr.\nOrganisatie:\n- spelers staan kris kras door elkaar.\n- de trainer geeft eerst een beeld van de\noefening en controleert daarna de uitvoering .\nAanwijzingen\nVoor de beschrijving van de techniek, zie\ntechnieklijst."}, {"type": "partijvorm", "title": "STAP 2.4 B: VOOR POSITIE-PARTIJSPELEN (3:0)", "content": "Alle spelers staan voorwaarts gericht en speler 2 start de oefening\nmet een keuzemogelijkheid:\nA. Speler 2 kan de bal zowel met de linker- als met de\nrechterbinnenkant van de voet doorspelen naar speler 3.\nB. Speler 3 neemt de bal met de rechterbinnenkant van de voet\naan en dribbelt voorwaarts.\nC.Speler 3 speelt de bal met de rechterbinnenkant van de voet\nterug naar speler 2.\nD. Speler 2 neemt de bal met de linkerbinnenkant van de voet\naan en kan de bal zowel met de linker- als met de\nrechterbinnenkant van de voet doorspelen naar speler 1.\nE. Idem.\nVariatie in uitvoering:\nIdem in tegengestelde richting met het andere been.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 15 bij 10m\nE-pupillen: 20 bij 15m\nD-pupillen: 25 bij 20m\nC-,B-,A-junioren: 30 bij 25m\nAanwijzingen\nAanbieden:\n- Na de aanname van de medespeler om de\nbal vragen.\nAannemen:\n- Voor je, binnen je bereik.\n- Na de aanname snelheid houden voor de\nvolgende actie.\n- Naar voren gerichte open aanname.\n- Bal vlakbij of voorbij het standbeen\naannemen.\nSTAP 1: KONINGSPEL MET STOPPEN VAN DE BAL\nMethodiek\nElke speler heeft een bal en op een teken van de trainer dribbelen\nde spelers vanuit het beginvak naar het eindvak aan de overkant.\nOnderweg probeert de \"balafpakker\" de ballen van de andere\nspelers uit het vierkant te schieten.\n- bal kwijt dan wordt je ook \"balafpakker\".\n- winnaar is de speler die overblijft.\nVariatie in aanbieden:\n- elke speler start met 3 punten. Bij balverlies gaat er telkens 1\npunt af.\n- bij 0 punten is de speler af.\n- winnaar is degene die over blijft!\nMaterialen\nAantal spelers: 6-8\nHoedjes: 6\nAantal ballen: elke speler 1 bal, behalve de\nbalafpakker\nAantal pylonen: 6\nAfstand tussen de pylonen: speelveld: ongeveer\n10 bij 15 meter\nAanwijzingen\nSpelers coachen op:\n- de bal dichtbij je houden.\n- de bal goed afschermen.\n- een andere kant opgaan als de tikker naar\nje toekomt.\n- probeer snel de overkant te bereiken.\n- afkappen over de achterlijn."}, {"type": "techniek", "title": "LIJNDRIBBEL 3:2 MET DOEL", "content": "d.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O9', 13, '{"session_a": [{"type": "warming_up", "title": "SPIEGELEN (1)", "content": "Oefeningen, waarbij de speler(s) de door de tegenstander uitgevoerde stappen\nvan de onderstaande technieken, op de plaats, nadoet(n).\n1. Trippling (Stap 1, 2)\n2. Skipping (Stap 1, 2, 3)\n3. Hielaanslag ( Stap 1)\nOpgelet!\n- alleen uitvoeren als de spelers bekend zijn met bovenstaande technieken.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nDe pylonen vormen een rechte lijn van 2 mtr.\nOrganisatie:\n- de spelers staan hierbij recht tegenover één speler die de leiding heeft. Zij\nmoeten daarbij zijn bewegingen volgen (spiegelen).\n2 TEGEN 1\nMethodiek\nIn ieder vak van 3 aaneengeschakelde vakken staat een speler.\nDe speler in het middelste vak is de lummel.\nDe spelers in de buitenste vakken proberen de bal over te spelen\ndoor het middelste vak heen, zonder dat de lummel de bal\nonderschept.\nAls de lummel de bal onderschept moet de speler die de bal als\nlaatste aanraakte / speelde wisselen met de lummel.\nAls de bal buiten de buitenste vakken komt, wordt de speler die\nals laatste de bal raakte de lummel.\nVariatie:\n- per X-aantal keer overspelen krijgen de ''''balbezitters'' een punt\n- de bal moet in beweging blijven, dus de balbezitters mogen niet\nstil gaan staan met de bal.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: 3-tal 1 bal\nAantal pylonen: 8\nAfstand pylonen: 8 bij 8 meter\nAanwijzingen\nSpelers coachen op:\n- Schieten met de binnenkant van de voet.\n- Speelbeen loodrecht op de speelrichting.\n- Voetzool parallel met de grond."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet,\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- De Overstap (Stap 3)\n- Kappen buitenkant voet (Stap 1+2)\n- Binnen-buitenkant wegdraai (Stap 1+2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 1: Het aanleren van de techniek De Overstap (Stap 4).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu de oefening met het andere been\nuitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "IN STROOMVORM (1)", "content": "Deze oefenvorm wordt uitgevoerd met twee rijen spelers.\nA. De spelers 1 dribbelen de bal naar de eerste pylon.\nB. Ter hoogte daarvan passen de spelers 1 de bal op de kaatser\nen lopen daarna door om de bal in de loop terug te krijgen.\nC. Vervolgens schieten de spelers 1 de bal met de\nbinnenkant/wreef van de rechtervoet op doel.\nOpgelet!\nDe volgende speler start pas nadat er op doel geschoten is.\nDe spelers moeten de bal in één keer schieten en vooral niet stil\ngaan staan om te schieten.\nVariatie in uitvoering:\n- Idem andersom met het andere been.\n- Vergroot/verklein de afstand ten opzichte van het schietpunt en/\nof het vak.\nMaterialen\nAantal spelers: 8- 12\nAantal pylonen: 8\nAantal ballen: 8-12\nBreedte speelveld: 20m\nDoelen: 2\nF-,E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen:\nStartafstand vanaf doel:\n2e jaars F-pupillen: 11 m\n1e jaars E-pupillen: 13 m\n2e jaars E-pupillen: 15 m\nD-pupillen: 17 m\nC-,B-,A-junioren: >19 m\nAfstand kaatser vanaf doel:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- De spelers staan in twee groepen verdeeld ter\nhoogte van het ene doel en tegenover het\nandere doel.\n- Nadat de speler geschoten heeft, haalt hij zijn\neigen bal op en sluit achter in de andere rij aan.\nAanwijzingen\nSpelers coachen op:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "AANGEEF SPEL", "content": "Elk tweetal heeft een bal. Van elk tweetal gaat er één als aangever voor alle\nandere spelers aan de zijlijn staan. De spelers zonder bal proberen lopende door\nhet hele vak, telkens gedurende 1 minuut, bij een \"vrije aangever\"de bal te\nvragen. Deze gooit de bal aan en de speler kan de bal op de volgende wijze\nterugspelen:\n- Koppen\n- Terugpassen over de grond\n- Terugpassen door de lucht\n- Aannemen op de borst en terugspelen\nOpgelet!\nBlijf niet bij een aangever hangen.\nMaterialen\nTijd: 10-15 min\nRonde tijden: 1 a 2 min\nPylonen: 4 pylonen om het speelveld uit te zetten\nBallen: iedere speler heeft een bal."}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ZELFDE/ANDERE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met dezelfde voet.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "C. TEGENSTANDER VOOR JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Uitstappen meenemen (Stap 3)\n- Akka (binnen-buiten) (Stap 1)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 4) en Akka (binnen-buiten) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n(3 : 1) OEFENING 1\nMethodiek\nREGELS:\n• Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• 3x bal afnemen is wisselen van taak met de aanvaller die het\nlangst niet in het midden heeft gestaan.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 4\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nORGANISATIE:\n• De 3 spelers nemen positie in op 3 van de 4\nzijden.\n• De verdediger neemt de positie in het midden\nin\n• De bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het goed aanspeelbaar zijn aan beide\nzijden van de speler in balbezit.\n• het goed vragen om de bal aan de kant van\nde bal.\n• het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n• het zoveel mogelijk over de bal heen kijken.\nVERDEDIGER COACHEN OP:\n• Druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O9', 14, '{"session_a": [{"type": "warming_up", "title": "HIELAANSLAG-ESTAFETTE", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek in voorwaartse richting uitvoert(en) tot bij de medespeler\naan de andere kant. Ondertussen voert hij daarbij de hielslag uit,\nterwijl hij de bal met een lichte hoek in de ellebogen in de handen\nvoor het lichaam houdt. Aan de overkant gekomen geeft hij de bal\nover en zijn medespeler voert vervolgens ook de oefening in\ntegengestelde richting uit.\n1. Hielaanslag (Stap 2)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler stap 2 van de hielaanslag beheerst.\nMaterialen\nAantal spelers: 10\nAantal ballen: 2\nAantal pylonen: 4\nOrganisatie:\nDe spelers( 3 aan de ene en 2 aan de andere\nkant) staan verdeeld in 2 rijen achter de op een\nonderlinge afstand van 15 mtr. geplaatste\npylonen tegenover elkaar.De voorste speler\nheeft een bal in de handen en start de oefening\nWinnaar is de rij die het eerst de oefening\nuitgevoerd heeft\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSTAP 2.2 A: AANBIEDEN, HEEN/TERUG IN LIJNVORM COMBINATIE\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 speelt de bal met de binnenkant van de linker-\n/rechtervoet.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 2 kaatst de bal met de binnenkant van de linker-\n/rechtervoet terug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 kaatst de bal met de binnenkant van de linker-\n/rechtervoet.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet,\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- De Overstap (Stap 3)\n- Kappen buitenkant voet (Stap 1+2)\n- Binnen-buitenkant wegdraai (Stap 1+2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 2: Het aanleren van de techniek Kappen buitenkant voet\n(Stap 3). Het oefenen van de techniek De Overstap (Stap 4).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu de oefening met het andere been\nuitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}], "session_b": [{"type": "warming_up", "title": "KRISKRASORGANISATIE (1)", "content": "Spelers voeren één van de stappen van de onderstaande\ntechnieken uit, terwijl zij met de bal aan de voet , zonder elkaar te\nhinderen, door het hele vak bewegen.\n- Schaar en Pirouette (Stap 2)\n- Sleep (Stap 1)\n- Uitstappen/meenemen (Stap 2)\n- De Overstap (Stap 2)\n- De Schijntrap (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 4\nDe pylonen vormen een rechthoek van 10 bij 8\nmtr.\nOrganisatie:\nSpelers staan kris kras door elkaar.\nDe trainer geeft eerst een beeld van de oefening\nen controleert daarna de uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.3 A: VOOR POSITIESPELEN (3:0)", "content": "Bij deze oefening is het belangrijk dat de speler in balbezit 2\nspeelmogelijkheden heeft.\nDe aanbiedende spelers moeten, om aanspeelbaar te kunnen zijn,\naan beide zijden vrijkomen.\nDeze spelers kunnen hierbij de bal op de volgende manier\nverwerken:\n- Links aannemen en links doorspelen\n- Links aannemen en rechts doorspelen\n- Rechts aannemen en rechts doorspelen\n- Rechts aannemen en links doorspelen.\nDe spelers hebben dan de volgende afspeelmogelijkheden:\n- Speler 1 kan op 2 en 3 spelen\n- Speler 2 kan op 1 en 3 spelen\n- Speler 3 kan op 1 en 2 spelen\nVariatie in uitvoering:\n- Inspelen met de klok mee\n- Inspelen tegen de klok in\n- Spelen op eigen intuïtie\n- Verhogen van speelsnelheid\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nmedespeler.\nAannemen:\n- Voor je liggen maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aanname, zodat de bal twee kanten\nopgespeeld kan worden.\nSTAP 1: PARCOURS DRIBBELEN/DRIJVEN\nMethodiek\nDe spelers slalommen dribbelend het hele parcours door en het\nrechte stuk leggen ze dribbelend/ drijvend af.\nVariatie in aanbieden:\n- varieer in uitvoeringssnelheid\n- varieer onderlinge afstand pylonen\n- voer de oefening in wedstrijdvorm uit.\nLet op!\n- speler 2 start wanneer speler 1 voorbij de tweede pylon is, enz.\nMaterialen\nAantal spelers: 4-10 spelers\nAantal pylonen: 7\nAantal ballen: elke speler 1 bal\nOnderlinge afstand pylonen: 3 a 5 meter\nAanwijzingen\nSpelers coachen op:\n- houd de bal dichtbij je, maar niet onder je\n- probeer de bal zoveel mogelijk te raken\n- probeer de bal bij iedere stap te raken, dan\nkun je de bal ook beter sturen\n- bij het drijven op het rechte stuk mag de\nbal iets verder vooruit gespeeld worden. Niet\nte ver, behoud wel de controle over de bal."}, {"type": "techniek", "title": "PARCOURS DRIBBELEN EN AFWERKEN", "content": "De spelers slalommen dribbelend het hele parcours door en werk\naf op doel.\nVariatie in aanbieden:\n- Varieer in uitvoeringssnelheid\n- Varieer onderlinge afstand pylonen.\n- Voer de oefening in wedstrijdvorm uit.\nVariatie\nVariatie 4: Parcours dribbelen met rechter en linker voet.\nMaterialen\nAantal spelers: 4-10\nAantal ballen: elke speler 1 bal\nAantal pylonen: 8\nDoelen: 2\nOnderlinge afstand pylonen: 2 a 3 meter\nAanwijzingen\nSpelers coachen op:\n- Houdt de bal dichtbij je, maar niet onder je.\n- Probeer de bal zoveel mogelijk te raken.\n- Probeer de bal bij iedere stap te raken, dan\nkun je de bal ook beter sturen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O9', 15, '{"session_a": [{"type": "test", "title": "SPEEDLADDER (1)", "content": "Is een oefening, waarbij de voorwaartse vormen worden\naangeleerd in de speedladder. De oefening is opgebouwd van\ngrove motoriek naar de fijne motoriek. Dat wil zeggen binnen de\nlooptraining, er wordt gewerkt van een skipping naar skipping 45\ngraden en vervolgens naar kort voetenwerk.\nStap 1: Eén voetje in het raam plaatsen.\nStap 2: Twee voetjes in het raam plaatsen.\nStap 3: Drie voetjes in het raam plaatsen.\nDifferentiatie:\nStroop de ladder op, zodat er door de spelers ten alle tijden een\nskipping ingezet moet worden.\nLet op!\nDeze vormen kunnen spelenderwijs worden aangeleerd.\nMaterialen\nAantal spelers: het gehele team.\nAantal speedladders:\nEén, bij voorkeur twee.\nAantal pylonnen:\nEén\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ZELFDE/ANDERE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met dezelfde voet.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 4) en\nAkka (buiten-binnen) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "(3 : 1) OEFENING 2", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden (omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 3 spelers nemen positie in op 3 van de 4\nzijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "BEVRIJDINGSTIKKERTJE", "content": "Eén speler probeert als tikker de andere spelers te tikken.\nDe getikte spelers gaan naar het bevrijdingsvak. Elke \"vrije\nspeler\" mag hen weer \"vrij\" tikken.\nVariatie:\nTwee of meerdere tikkers\nMaterialen\nDuur: 10-15 min\nDuur ronde: 1 a 2 min\nAantal: 8-20\nPylonen:\n- 4 om het speelveld af te bakenen.\n- 3/4 om het bevrijdingsvak aan te geven.\nAanwijzingen\nWedstrijdoptie:\nTel aan het eind het aantal spelers in het\nbevrijdingsvak.\nSTAP 2.2 A: AANBIEDEN, HEEN/TERUG IN LIJNVORM COMBINATIE\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 speelt de bal met de binnenkant van de linker-\n/rechtervoet.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 2 kaatst de bal met de binnenkant van de linker-\n/rechtervoet terug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 kaatst de bal met de binnenkant van de linker-\n/rechtervoet.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 4), Sleep (Stap 3) en Akka (binnen-voor) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O9', 16, '{"session_a": [{"type": "test", "title": "WENDBAARHEIDSTEST 1", "content": "Voor deze test wordt in het strafschopgebied, tussen de doellijn\nen de rand van het gebied, een parcours ( zie tekening) uitgezet.\nHet protocol voor deze test luidt als volgt:\nDe test start vanuit buikligging. Vervolgens wordt het hele traject\nin korte sprintjes, van pylon naar pylon, afgelegd.\nDe pylonen worden daarbij,tot het bereiken van de finish, telkens\nzo kort mogelijk gerond.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen:8\nAfstand tussen de pylonen:gebruik de\naangegeven lijnen en verdeel de tussenliggende\nruimte gelijkmatig\nSchrijfbenodigdheden\nAanwijzingen\n- ontwikkel, zowel heen als terug, een zo\nhoog mogelijke snelheid\n- draai kort om de pylon\n- neem minimaal 2-3 minuten rust tussen\ntwee testen\n2 TEGEN 1\nMethodiek\nIn ieder vak van 3 aaneengeschakelde vakken staat een speler.\nDe speler in het middelste vak is de lummel.\nDe spelers in de buitenste vakken proberen de bal over te spelen\ndoor het middelste vak heen, zonder dat de lummel de bal\nonderschept.\nAls de lummel de bal onderschept moet de speler die de bal als\nlaatste aanraakte / speelde wisselen met de lummel.\nAls de bal buiten de buitenste vakken komt, wordt de speler die\nals laatste de bal raakte de lummel.\nVariatie:\n- per X-aantal keer overspelen krijgen de ''''balbezitters'' een punt\n- de bal moet in beweging blijven, dus de balbezitters mogen niet\nstil gaan staan met de bal.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: 3-tal 1 bal\nAantal pylonen: 8\nAfstand pylonen: 8 bij 8 meter\nAanwijzingen\nSpelers coachen op:\n- Schieten met de binnenkant van de voet.\n- Speelbeen loodrecht op de speelrichting.\n- Voetzool parallel met de grond."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet,\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- De Overstap (Stap 3)\n- Kappen buitenkant voet (Stap 1+2)\n- Binnen-buitenkant wegdraai (Stap 1+2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het aanleren van de techniek Binnen buiten wegdraai\n(Stap 3+4). Het oefenen van de techniek De Overstap (Stap 4) en\nKappen buitenkant voet (Stap 3).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu de oefening met het andere been\nuitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\n- Binnen-buitenkant wegdraai (Stap 4)\nA. Speler 1 start de oefening door de bal met de rechter\nbinnenkant van de voet op de aanbiedende speler 2 te\npassen(deze doet alsof hij een speler in de rug heeft).\nB. Speler 2 ontvangt de bal en voert vervolgens één van de\nbovengenoemde technieken uit.\nC. Daarna dribbelt hij richting doel om vervolgens hierop af te\nronden.\nD. Speler 2 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 loopt door naar de volgende pylon en\nneemt de positie over van speler 2.\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\nIdem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "LIJNORGANISATIE (1)", "content": "Eén van de stappen van de onderstaande technieken dient, heen\nen terug tussen de lange zijden van de rechthoek, uitgevoerd te\nworden.\n- Schaar en Pirouette (Stap 2)\n- Sleep (Stap 1)\n- Uitstappen/meenemen (Stap 2)\n- De Overstap (Stap 2)\n- De Schijntrap (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 2-16 (per speler twee pylonen)\nTwee rijen pylonen op een onderlinge afstand\nvan 8 mtr.\nOrganisatie:\nDe trainer geeft eerst een beeld van de oefening\nen controleert daarna de uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ZELFDE/ANDERE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met dezelfde voet.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 1: DRIBBELKONING", "content": "Elke speler heeft een bal en dribbelt door het vierkant. Twee\n\"balafpakkers\" proberen de ballen van de andere spelers uit het\nvak te schieten.\nBal kwijt, dan wordt je ook \"balafpakker\".\nDe speler die overblijft is dribbelkoning.\nVariatie:\n- bij een te kleine groep volstaat 1 \"balafpakker\".\nMaterialen\nAantal spelers: 6-8\nAantal ballen: elke speler 1 bal, behalve 2\nbalafpakkers\nHesjes: de balafpakkers\nAantal pylonen: 4\nAfstand tussen de pylonen: speelveld: ongeveer\n10 bij 15 meter\nAanwijzingen\nSpelers coachen op:\n- de bal dichtbij je houden.\n- de bal goed afschermen.\n- een andere kant opgaan als de afpakker\nnaar je toekomt.\n(3 : 1) OEFENING 2\nMethodiek\nDrie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden (omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 3 spelers nemen positie in op 3 van de 4\nzijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O9', 17, '{"session_a": [{"type": "warming_up", "title": "REACTIE-ACTIE", "content": "Dit is een oefening voor het hele team. Het hele team zit/ ligt hierbij op de\nachterlijn van het 16-metergebied. Op een teken van de trainer (b.v. “JA”) staan\nde spelers op en versnellen naar de overkant.\nDifferentiatie:\n- varieer in de uitgangshouding, zoals zitten op de billen, liggen op de buik, -\nzijde (beide kanten) of op de rug.\nWees daarbij creatief!\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: gehele team.\nOrganisatie:\nAchterlijn 16-meter gebied."}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ZELFDE/ANDERE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met dezelfde voet.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 1: Aanbieden voorwaarts en achterwaarts\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN LIJNVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan (deze doet alsof hij een speler in de rug heeft).\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen-buitenkant wegdraai (Stap 4)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 6\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 6.\nIdem voor de spelers 4,5 en 6 in tegengestelde richting, etc.\nVariatie:\nIdem, maar nu met het andere been uitvoeren.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 3\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt, na de pass op speler 2, diens\nplaats in. Speler 2 dribbelt naar speler 6 en geeft\nhem de bal. Speler 4 neemt, na de pass op\nspeler 5, diens plaats in en speler 5 geeft de bal\naan speler 3, etc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "LIJNDRIBBEL 3:2 MET DOEL", "content": "d.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "LIJNEN SPEL", "content": "De spelers staan met de bal aan de voet op een door de trainer\naangegeven lijn van het 16- meter gebied. Op zijn teken dribbelen\nde spelers naar een door de trainer aangegeven andere lijn.\nOpgelet!\nGeen 16- meter gebied beschikbaar, maak dan gebruik van\nverschillend gekleurde pylonen of hoedjes om daarmee lijnen te\nvormen\nMaak bij de\" jongste jeugd\" gebruik van nummers.\nVariatie:\n- Geef elke speler bij aanvang 3 punten en haal bij de laatste\ntelkens 1 punt af. Winnaar is ook nu weer degene die over blijft.\n- Laatste valt steeds af en winnaar is degene die over blijft (alleen\ndoen als afsluiting van een training).\nMaterialen\nAantal spelers: 4-14\nAantal pylonen: 10 (om eventueel de lijnen aan\nte geven)\nAantal ballen: elke speler 1 bal\nAanwijzingen\nSpelers coachen op:\n- Draai eerst proef.\n- De bal moet wel steeds op de lijn onder de\nvoet stil liggen.\nSTAP 2.2 A: AANBIEDEN, HEEN/TERUG IN LIJNVORM COMBINATIE\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 speelt de bal met de binnenkant van de linker-\n/rechtervoet.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 2 kaatst de bal met de binnenkant van de linker-\n/rechtervoet terug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 kaatst de bal met de binnenkant van de linker-\n/rechtervoet.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "STAP 2 C: DRIBBELEN (PLUSVORM, TOT 90º)", "content": "A. Speler 1 speelt naar speler 2.\n- speler 1 speelt de bal op de \"naar links\" aanbiedende speler 2\n- speler 1 loopt achter de bal aan naar de plaats van speler 2.\nB. Speler 2 dribbelt naar volgende pylon.\n- speler 2 neemt de bal \"naar links\" opengedraaid met links aan\nen dribbelt de bal, met de buitenkant van de linkervoet, naar de\nvolgende pylon.\nC. Speler 2 speelt naar speler 1.\n- speler 2 speelt de bal op de \"naar rechts\" aanbiedende speler 1,\netc.\nIdem, voor spelers 3 en 4; 5 en 6; 7 en 8.\nVariatie in aanbieden:\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 8\nAantal ballen: 4\nAantal pylonen: 4\nAfstand tussen pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAannemen van de bal:\n- open aanname, gericht naar voren.\n- snelheid houden na de aanname voor de\nvolgende actie.\nDribbelen van de bal:\n- speelbeen: Bal steeds zodanig en zo vaak\nraken dat hij in het looptempo en in goede\nrichting kan worden meegenomen \"bal aan\nelastiekje\".\n- raakvlak: Het beroeren van de bal\nafwisselend met wreef, binnen- en buitenkant\nvan de voet afhankelijk van\nrichtingsverandering.\n- over de bal heen kijken."}, {"type": "techniek", "title": "AANBIEDEN, TOT 45º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: 4-6\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O9', 18, '{"session_a": [{"type": "warming_up", "title": "BALGOOCHELAAR", "content": "Oefeningen, waarbij de spelers de stappen van de onderstaande\ntechnieken, op de plaats/ in voorwaartse richting moeten\nuitvoeren. De speler heeft daarbij een bal in de handen die hij, op\neen teken van de trainer, in verschillende standen langs zijn\nlichaam moet brengen..\n1. Tripling (Stap 1, 2, 3 en 4)\n2. Skipping ( Stap 1, 2, 3 en 4)\n3. Hielaanslag (Stap 1 en 2)\nOpgelet!\nDeze oefening kan ook uitgevoerd worden als aanleervorm.\nDoor de bal in verschillende posities te houden wordt er veel\ngevraagd van de rompstabiliteit van de speler. (Rompstabiliteit:\nhet stilhouden van het bovenlichaam.)\nMaterialen\nAantal spelers: 15\nAantal pylonen: 0\nAantal ballen: 15\nOrganisatie:\nDe spelers staan kris kras door elkaar in het 16-\nmeter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 B: AANBIEDEN, TOT 45º (ZELFDE/ANDERE BEEN) IN DRIEHOEKSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 1\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met dezelfde voet.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- De verandering (Stap 2)\n- Kappen binnenkant voet (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 1: Het aanleren van de techniek De verandering (Stap 3).\nMaterialen\nAantal spelers: 6-9\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n(3 : 1) OEFENING 2\nMethodiek\nDrie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden (omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 3 spelers nemen positie in op 3 van de 4\nzijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}], "session_b": [{"type": "warming_up", "title": "PAALTJES VOETBAL 1", "content": "Het spel wordt gespeeld met 1 bal en elke speler start met 3\npunten. Alle spelers krijgen ergens in het vak een pylon te\nverdedigen. De spelers moeten proberen de pylon van elkaar\nomver te schieten. Gebeurt dit dan gaat er bij de desbetreffende\nspeler een punt af . Uiteindelijk blijft er 1 speler, de winnaar, over.\nVariatie:\nEen tweede bal in het spel brengen.\nOpgelet!\nBlijf niet voor je pylon hangen!\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nPylon: voor iedere speler 1\nBallen: 1-2\nAanwijzingen\nAls een speler geen punten meer heeft dan\ngaat hij aan de kant staan."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º (ZELFDE/ANDERE BEEN) IN VIERKANTVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Spelers 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 1: Aanbieden voorwaarts en achterwaarts\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "PARCOURS DRIBBELEN EN AFWERKEN", "content": "De spelers slalommen dribbelend het hele parcours door en werk\naf op doel.\nVariatie in aanbieden:\n- Varieer in uitvoeringssnelheid\n- Varieer onderlinge afstand pylonen.\n- Voer de oefening in wedstrijdvorm uit.\nVariatie\nVariatie 4: Parcours dribbelen met rechter en linker voet.\nMaterialen\nAantal spelers: 4-10\nAantal ballen: elke speler 1 bal\nAantal pylonen: 8\nDoelen: 2\nOnderlinge afstand pylonen: 2 a 3 meter\nAanwijzingen\nSpelers coachen op:\n- Houdt de bal dichtbij je, maar niet onder je.\n- Probeer de bal zoveel mogelijk te raken.\n- Probeer de bal bij iedere stap te raken, dan\nkun je de bal ook beter sturen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O9', 19, '{"session_a": [{"type": "warming_up", "title": "KNIEHEF TIKKERTJE / HAKKEN-BIL TIKKERTJE", "content": "Dit is een oefening, waarbij de speler(s) de stap van één van de onderstaande\ntechnieken uitvoeren in de vorm van een tikspel. Eén speler moet, als tikker, de\nandere spelers proberen te tikken, terwijl zij (tikker en overige spelers) tijdens\nhet lopen één van de onderstaande technieken verwerken in hun looptechniek.\n1. Skipping (Stap 4)\n2. Hielaanslag (Stap 2)\nTerug komen tijdens het tikspel:\n- hierbij wordt gewerkt vanuit het principe “3 is te veel”.Dat wil zeggen dat\ntelkens als er een derde speler bij de 2 langs de kant staande afgetikte spelers\naansluit, de eerste afgetikte speler weer mee gaat doen aan het spel.\nDifferentiatie:\n- bij dit spel kan je het aantal tikkers variëren.\nOpgelet!\n- dit zijn introductievormen voor de looptraining.\nMaterialen\nAantal spelers: 15\nOrganisatie:\n- de afmeting van het vak is 10 bij 15 meter.\n2 TEGEN 1\nMethodiek\nIn ieder vak van 3 aaneengeschakelde vakken staat een speler.\nDe speler in het middelste vak is de lummel.\nDe spelers in de buitenste vakken proberen de bal over te spelen\ndoor het middelste vak heen, zonder dat de lummel de bal\nonderschept.\nAls de lummel de bal onderschept moet de speler die de bal als\nlaatste aanraakte / speelde wisselen met de lummel.\nAls de bal buiten de buitenste vakken komt, wordt de speler die\nals laatste de bal raakte de lummel.\nVariatie:\n- per X-aantal keer overspelen krijgen de ''''balbezitters'' een punt\n- de bal moet in beweging blijven, dus de balbezitters mogen niet\nstil gaan staan met de bal.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: 3-tal 1 bal\nAantal pylonen: 8\nAfstand pylonen: 8 bij 8 meter\nAanwijzingen\nSpelers coachen op:\n- Schieten met de binnenkant van de voet.\n- Speelbeen loodrecht op de speelrichting.\n- Voetzool parallel met de grond."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- De verandering (Stap 2)\n- Kappen binnenkant voet (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 2: Het aanleren van de techniek Kappen binnenkant voet\n(Stap 3). Het oefenen van de techniek De verandering (Stap 3).\nMaterialen\nAantal spelers: 6-9\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nTEGENSTANDER NAAST JE: IN STROOMVORM\nMethodiek\nDeze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- De verandering (Stap 4A)\n- Kappen achter het standbeen (Stap 3A)\n- Kappen binnenkant voet (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna dribbelt hij, met de bal aan de voet, richting doel om\nvervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\nSpeler 1 haalt de bal en sluit achter in de andere\nrij aan.\nIdem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "DRIE IS TEVEEL", "content": "De spelers vormen naast elkaar staande tweetallen verspreid over\nhet hele vak. Twee spelers, 1 loper en 1 tikker vormen geen\ntweetal. De loper probeert de tikker te ontlopen en kan zich\ndaarbij vrijspelen door naast een tweetal te gaan staan.\nDe speler die aan de andere buitenkant komt te staan wordt\ndaardoor de nieuwe loper, die getikt moet worden.\nOpgelet!\nEen getikte speler wordt direct de nieuwe tikker.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 12 of meer spelers\nPylonen: 4 om het speelveld af te bakenen.\nAanwijzingen\n- De spelers moeten stil op hun plek blijven\nstaan"}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º (ZELFDE/ANDERE BEEN) IN VIERKANTVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Spelers 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "C. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 4) en Akka (binnen-buiten) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "(3 : 1) OEFENING 3", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nDe aanvaller die een fout maakt wordt verdediger\nUitvoering:\n- In spelvorm 5x samenspel = 1 pnt.\n- aanraken/afpakken of lijndribbel =1 pnt.\n- wisselen van taak bij 5 pnt.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 3 spelers nemen positie in op 3 van de 4\nzijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken.\nPARTIJVORM 1:1\nMethodiek\nEén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O9', 20, '{"session_a": [{"type": "warming_up", "title": "OMSCHAKELINGSTIKKERTJE", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nOp een teken van de trainer probeert de speler uit de ene groep de andere\nspeler van het tweetal uit de andere groep te tikken.\nNadat hij hem getikt heeft draait hij direct van hem weg en versnelt naar de\nzijlijn. De andere speler probeert op zijn beurt de eerste speler, nog voordat hij\nde zijlijn heeft gepasseerd, te tikken.\nDifferentiatie gemakkelijk:\n- het spel “koe-kopen”.\nDifferentiatie moeilijk:\n- er kan gevarieerd worden door spelers met een bal aan de zijlijn te laten staan,\nom een kaats aan te gaan met de weggedraaide speler. Hij komt hierbij als het\nware in de bal. Omschakeling met bal (1)\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- de afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (1)", "content": "A. Spelers 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar links\"aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 4.\n- Speler 3 sluit achter speler 4 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- Idem, andersom met het andere been.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- De verandering (Stap 2)\n- Kappen binnenkant voet (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Kappen binnenkant\nvoet (Stap 3) en De verandering (Stap 3).\nMaterialen\nAantal spelers: 6-9\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "LIJNORGANISATIE (2)", "content": "Eén van de stappen van de onderstaande technieken dient, heen\nen terug tussen de lange zijden van de rechthoek, uitgevoerd te\nworden.\n- Aai buitenkant voet (Stap 1)\n- Kappen achter standbeen (Stap 1)\n- Pirouette (Stap 3)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 2-16 (per speler twee pylonen)\nTwee rijen pylonen op een onderlinge afstand\nvan 8 mtr.\nOrganisatie:\nDe trainer geeft eerst een beeld van de oefening\nen controleert daarna de uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 4) en\nAkka (buiten-binnen) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º (ZELFDE/ANDERE BEEN) IN VIERKANTVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Spelers 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 90º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O9', 21, '{"session_a": [{"type": "warming_up", "title": "SPIEGELEN (1)", "content": "Oefeningen, waarbij de speler(s) de door de tegenstander uitgevoerde stappen\nvan de onderstaande technieken, op de plaats, nadoet(n).\n1. Trippling (Stap 1, 2)\n2. Skipping (Stap 1, 2, 3)\n3. Hielaanslag ( Stap 1)\nOpgelet!\n- alleen uitvoeren als de spelers bekend zijn met bovenstaande technieken.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nDe pylonen vormen een rechte lijn van 2 mtr.\nOrganisatie:\n- de spelers staan hierbij recht tegenover één speler die de leiding heeft. Zij\nmoeten daarbij zijn bewegingen volgen (spiegelen)."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (1)", "content": "A. Spelers 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar links\"aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 4.\n- Speler 3 sluit achter speler 4 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- Idem, andersom met het andere been.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 4), Sleep (Stap 3) en Akka (binnen-voor) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "(3 : 1) OEFENING 1", "content": "REGELS:\n• Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• 3x bal afnemen is wisselen van taak met de aanvaller die het\nlangst niet in het midden heeft gestaan.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 4\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nORGANISATIE:\n• De 3 spelers nemen positie in op 3 van de 4\nzijden.\n• De verdediger neemt de positie in het midden\nin\n• De bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het goed aanspeelbaar zijn aan beide\nzijden van de speler in balbezit.\n• het goed vragen om de bal aan de kant van\nde bal.\n• het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n• het zoveel mogelijk over de bal heen kijken.\nVERDEDIGER COACHEN OP:\n• Druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "SNIJ TIKKERTJE", "content": "Eén speler probeert als tikker de andere spelers te tikken. De\ntikker moet, als een andere speler de achtervolging doorkruist,\nvan achtervolgde wisselen. Hij moet nu de andere speler gaan\nachtervolgen.\nOpgelet!\n- naar eigen inzicht wisselen van tikker.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 6-12 spelers\nPylonen: 4 om het speelveld af te bakenen.\nAanwijzingen\n- een getikte wordt de nieuwe tikker.\n- de tikker bepaald van te voren wie hij gaat\ntikken.\n- dit spel kan verwarring veroorzaken. Houd\nde lijn van kruisen goed in de gaten."}, {"type": "techniek", "title": "STAP 2.3 A: VOOR POSITIESPELEN (3:0)", "content": "Bij deze oefening is het belangrijk dat de speler in balbezit 2\nspeelmogelijkheden heeft.\nDe aanbiedende spelers moeten, om aanspeelbaar te kunnen zijn,\naan beide zijden vrijkomen.\nDeze spelers kunnen hierbij de bal op de volgende manier\nverwerken:\n- Links aannemen en links doorspelen\n- Links aannemen en rechts doorspelen\n- Rechts aannemen en rechts doorspelen\n- Rechts aannemen en links doorspelen.\nDe spelers hebben dan de volgende afspeelmogelijkheden:\n- Speler 1 kan op 2 en 3 spelen\n- Speler 2 kan op 1 en 3 spelen\n- Speler 3 kan op 1 en 2 spelen\nVariatie in uitvoering:\n- Inspelen met de klok mee\n- Inspelen tegen de klok in\n- Spelen op eigen intuïtie\n- Verhogen van speelsnelheid\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nmedespeler.\nAannemen:\n- Voor je liggen maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aanname, zodat de bal twee kanten\nopgespeeld kan worden.\nSTAP 2 C: DRIBBELEN (PLUSVORM, TOT 90º)\nMethodiek\nA. Speler 1 speelt naar speler 2.\n- speler 1 speelt de bal op de \"naar links\" aanbiedende speler 2\n- speler 1 loopt achter de bal aan naar de plaats van speler 2.\nB. Speler 2 dribbelt naar volgende pylon.\n- speler 2 neemt de bal \"naar links\" opengedraaid met links aan\nen dribbelt de bal, met de buitenkant van de linkervoet, naar de\nvolgende pylon.\nC. Speler 2 speelt naar speler 1.\n- speler 2 speelt de bal op de \"naar rechts\" aanbiedende speler 1,\netc.\nIdem, voor spelers 3 en 4; 5 en 6; 7 en 8.\nVariatie in aanbieden:\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 8\nAantal ballen: 4\nAantal pylonen: 4\nAfstand tussen pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende\npylon.\nAanwijzingen\nAannemen van de bal:\n- open aanname, gericht naar voren.\n- snelheid houden na de aanname voor de\nvolgende actie.\nDribbelen van de bal:\n- speelbeen: Bal steeds zodanig en zo vaak\nraken dat hij in het looptempo en in goede\nrichting kan worden meegenomen \"bal aan\nelastiekje\".\n- raakvlak: Het beroeren van de bal\nafwisselend met wreef, binnen- en buitenkant\nvan de voet afhankelijk van\nrichtingsverandering.\n- over de bal heen kijken."}, {"type": "techniek", "title": "LIJNDRIBBEL 3:2 MET DOEL", "content": "d.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\nPARTIJVORM 1:1\nMethodiek\nEén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O9', 22, '{"session_a": [{"type": "warming_up", "title": "HIELAANSLAG-ESTAFETTE", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek in voorwaartse richting uitvoert(en) tot bij de medespeler\naan de andere kant. Ondertussen voert hij daarbij de hielslag uit,\nterwijl hij de bal met een lichte hoek in de ellebogen in de handen\nvoor het lichaam houdt. Aan de overkant gekomen geeft hij de bal\nover en zijn medespeler voert vervolgens ook de oefening in\ntegengestelde richting uit.\n1. Hielaanslag (Stap 2)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler stap 2 van de hielaanslag beheerst.\nMaterialen\nAantal spelers: 10\nAantal ballen: 2\nAantal pylonen: 4\nOrganisatie:\nDe spelers( 3 aan de ene en 2 aan de andere\nkant) staan verdeeld in 2 rijen achter de op een\nonderlinge afstand van 15 mtr. geplaatste\npylonen tegenover elkaar.De voorste speler\nheeft een bal in de handen en start de oefening\nWinnaar is de rij die het eerst de oefening\nuitgevoerd heeft\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "A. TEGENSTANDER NAAST JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nTEGENSTANDER NAAST JE: IN STROOMVORM\nMethodiek\nDeze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- De verandering (Stap 4A)\n- Kappen achter het standbeen (Stap 3A)\n- Kappen binnenkant voet (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna dribbelt hij, met de bal aan de voet, richting doel om\nvervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\nSpeler 1 haalt de bal en sluit achter in de andere\nrij aan.\nIdem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}], "session_b": [{"type": "warming_up", "title": "SIGNAALORGANISATIE (2)", "content": "De spelers voeren op een teken één van de stappen van de\nonderstaande technieken uit. De technieken zijn gekoppeld aan\neen nummer (1,2,3,4 etc.) of een naam en dienen verspreid over\nhet hele vak uitgevoerd te worden.\n- Schaar en Pirouette (Stap 2)\n- Sleep (Stap 1)\n- Uitstappen/meenemen (Stap 2)\n- De Overstap (Stap 2)\n- De Schijntrap (Stap 2)\nOpgelet!\n- alleen gebruiken als de spelers bekend zijn met de oefeningen.\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 4\nDe pylonen vormen een rechthoek van 10 bij 8\nmtr.\nOrganisatie:\n- de trainer geeft eerst vooraf een beeld van de\nuit te voeren techniek(en) en controleert daarna\nde uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek, zie\ntechnieklijst.\n2 TEGEN 1\nMethodiek\nIn ieder vak van 3 aaneengeschakelde vakken staat een speler.\nDe speler in het middelste vak is de lummel.\nDe spelers in de buitenste vakken proberen de bal over te spelen\ndoor het middelste vak heen, zonder dat de lummel de bal\nonderschept.\nAls de lummel de bal onderschept moet de speler die de bal als\nlaatste aanraakte / speelde wisselen met de lummel.\nAls de bal buiten de buitenste vakken komt, wordt de speler die\nals laatste de bal raakte de lummel.\nVariatie:\n- per X-aantal keer overspelen krijgen de ''''balbezitters'' een punt\n- de bal moet in beweging blijven, dus de balbezitters mogen niet\nstil gaan staan met de bal.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: 3-tal 1 bal\nAantal pylonen: 8\nAfstand pylonen: 8 bij 8 meter\nAanwijzingen\nSpelers coachen op:\n- Schieten met de binnenkant van de voet.\n- Speelbeen loodrecht op de speelrichting.\n- Voetzool parallel met de grond."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 3)\n- Binnen-buitenkant wegdraai (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het aanleren van de techniek Binnen buiten wegdraai\n(Stap 3+4). Het oefenen van de techniek De Overstap (Stap 4) en\nKappen buitenkant voet (Stap 3).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n(3 : 1) OEFENING 2\nMethodiek\nDrie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden (omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 3 spelers nemen positie in op 3 van de 4\nzijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O9', 23, '{"session_a": [{"type": "test", "title": "SPEEDLADDER (1)", "content": "Is een oefening, waarbij de voorwaartse vormen worden\naangeleerd in de speedladder. De oefening is opgebouwd van\ngrove motoriek naar de fijne motoriek. Dat wil zeggen binnen de\nlooptraining, er wordt gewerkt van een skipping naar skipping 45\ngraden en vervolgens naar kort voetenwerk.\nStap 1: Eén voetje in het raam plaatsen.\nStap 2: Twee voetjes in het raam plaatsen.\nStap 3: Drie voetjes in het raam plaatsen.\nDifferentiatie:\nStroop de ladder op, zodat er door de spelers ten alle tijden een\nskipping ingezet moet worden.\nLet op!\nDeze vormen kunnen spelenderwijs worden aangeleerd.\nMaterialen\nAantal spelers: het gehele team.\nAantal speedladders:\nEén, bij voorkeur twee.\nAantal pylonnen:\nEén\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "A. TEGENSTANDER NAAST JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "PLUSVORM (1)", "content": "Eén van de stappen van de onderstaande technieken dient heen\nen terug, in een plusvorm, van pylon naar pylon uitgevoerd te\nworden.\n- Schaar en Pirouette (Stap 2)\n- Sleep (Stap 1)\n- Uitstappen/meenemen (Stap 2)\n- De Overstap (Stap 2)\n- De Schijntrap (Stap 2)\nOpgelet!\n- handel bovenstaande technieken naar eigen inzicht af en\ngebruik hiervoor meerdere lessen/ organisatievormen (men moet\nelke techniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 5\nAfstand van buitenste naar middelste pylon\nbedraagt 8 mtr.\nOrganisatie:\n- de trainer geeft vooraf de uit te voeren\ntechniek(en) aan en controleert daarna de\nuitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek, zie\ntechnieklijst."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 4) en\nAkka (buiten-binnen) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 90º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "LIJNDRIBBEL 3:2 MET DOEL", "content": "d.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O9', 24, '{"session_a": [{"type": "warming_up", "title": "TENNISBALLENSPEL", "content": "Bij deze oefening wordt het ‘omschakelmoment’ van een speler\naangeleerd en getraind. Door deze oefening wordt een speler\nhandig in het lichtvoetig draaien. Tevens benadrukt deze oefening\nhet ‘laag zitten’ bij het wegdraaien bij de speler.\nOrganisatieuitleg:\nEr zijn bij het spel 4 pylonnen, 4 tennisballen en één hoepel\naanwezig. De pylonnen staan in een plusvorm en op de pylonnen\nliggen de tennisballen.\nSpeluitleg:\nDe speler begint in de hoepel, op een commando van de trainer\nstart de speler naar de eerste pylon. De speler pakt de tennisbal\nmet de rechterhand en geeft de bal over in zijn linkerhand en legt\nhem vervolgens in de hoepel. Vanuit de hoepel vertrekt de zelfde\nspeler naar de tweede pylon en pakt tevens weer een tennisbal\nvan de tweede pylon met zijn rechterhand, geeft deze weer over\nnaar zijn linkerhand en legt vervolgens de tennisbal weer in de\nhoepel. De speler vervolgt de zelfde volgorde ook bij de derde en\nvierde pylon.\nDifferentiatie:\nBiedt de vorm ook aan in een wedstrijdvorm, zodat de oefening\nook op maximale snelheid uitgevoerd moet worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal organisaties:\nZoveel als mogelijk.\nAantal pylonnen voor één organisatie: 4\npylonnen.\nAantal hoepels voor één organisatie:\n1 hoepel\nOrganisatie:\nPer situatie voert één speler de oefening uit.\nAanwijzingen\nLet op!\nZorg ervoor dat de oefening volledig wordt\nuitgevoerd. Dat de speler tevens bij elke\nomschakeling ‘laag zit’ (gebogen knieën\nheeft)."}, {"type": "techniek", "title": "STAP 2.2 A: AANBIEDEN, HEEN/TERUG IN LIJNVORM COMBINATIE", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 speelt de bal met de binnenkant van de linker-\n/rechtervoet.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 2 kaatst de bal met de binnenkant van de linker-\n/rechtervoet terug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 kaatst de bal met de binnenkant van de linker-\n/rechtervoet.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten.\nA. TEGENSTANDER NAAST JE: IN LIJNVORM\nMethodiek\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "B. TEGENSTANDER NAAST JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen achter het standbeen (Stap 2)\n- Kappen binnenkant voet (Stap 3)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n(3 : 1) OEFENING 3\nMethodiek\nDrie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nDe aanvaller die een fout maakt wordt verdediger\nUitvoering:\n- In spelvorm 5x samenspel = 1 pnt.\n- aanraken/afpakken of lijndribbel =1 pnt.\n- wisselen van taak bij 5 pnt.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 3 spelers nemen positie in op 3 van de 4\nzijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "SIGNAALORGANISATIE (3)", "content": "Spelers voeren op een teken één van de stappen van de\nonderstaande technieken uit. De technieken zijn gekoppeld aan\neen nummer (1,2,3 etc.) of een naam en dienen verspreid over\nhet hele vak uitgevoerd te worden.\n- Aai buitenkant voet (Stap 1)\n- Kappen achter standbeen (Stap 1)\n- Pirouette (Stap 3)\nOpgelet!\n- alleen gebruiken als de spelers bekend zijn met de oefeningen.\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 4\nDe pylonen vormen een rechthoek van 10 bij 8\nmtr.\nOrganisatie:\n- de trainer geeft eerst vooraf een beeld van de\nuit te voeren techniek(en) en controleert daarna\nde uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek, zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2 A: DRIBBELEN (LIJN/STROOMVORM, HEEN/TERUG)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet\nnaar speler 2.\n- Speler 1 loopt achter de bal aan naar speler 3 en sluit achter\nhem aan.\nB. Speler 2 dribbelt naar speler 1.\n- Speler 2 neemt de bal met rechts aan en dribbelt de bal, met de\nbuitenkant van de rechtervoet, terug.\n- Speler 2 neemt de plaats in van speler 1, etc.\nVariatie in uitvoering:\n- met links aannemen en dribbelen.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAannemen van de bal:\n- snelheid houden na de aanname voor de\nvolgende actie.\nDribbelen van de bal:\n- speelbeen: Bal steeds zodanig en zo vaak\nraken dat hij in het looptempo en in goede\nrichting kan worden meegenomen \"bal aan\nelastiekje\".\n- raakvlak: Het beroeren van de bal\nafwisselend met wreef, binnen- en buitenkant\nvan de voet afhankelijk van\nrichtingsverandering.\n- over de bal heen kijken.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O9', 25, '{"session_a": [{"type": "warming_up", "title": "DE OOIEVAAR", "content": "Is een oefening, waarbij de speler(s) de stap van één van de\nonderstaande technieken, op de plaats, moet(en)uitvoeren.\nBelangrijk hierbij is dat de speler na 5 skippings gedurende 5 tot\n10 seconden op zijn gehele voet stil blijft staan. Als de speler dit\nniet volhoud dan moet hij een sprint maken tot aan de 16-\nmeterlijn of tot bij de trainer.\n1. Skipping (Stap 3)\n2. Hielaanslag ( Stap 1)\nOpgelet!\nDit is een aanleervorm, waarbij de speler de stabiliteit in zijn been\n(knie/enkel), maar ook dat van zijn bovenlichaam (heup/borst)\nleert te beheersen.\nDifferentiatie:\n- Op de bal van de voet stilstaan\n- Uitvoering in voorwaartse richting.\n- Variëren in aantal skippings.\nMaterialen\nAantal spelers: gehele team\nOrganisatie:\nDe spelers staan kris kras door elkaar in het 16-\nmeter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2 C: DRIBBELEN (PLUSVORM, TOT 90º)", "content": "A. Speler 1 speelt naar speler 2.\n- speler 1 speelt de bal op de \"naar links\" aanbiedende speler 2\n- speler 1 loopt achter de bal aan naar de plaats van speler 2.\nB. Speler 2 dribbelt naar volgende pylon.\n- speler 2 neemt de bal \"naar links\" opengedraaid met links aan\nen dribbelt de bal, met de buitenkant van de linkervoet, naar de\nvolgende pylon.\nC. Speler 2 speelt naar speler 1.\n- speler 2 speelt de bal op de \"naar rechts\" aanbiedende speler 1,\netc.\nIdem, voor spelers 3 en 4; 5 en 6; 7 en 8.\nVariatie in aanbieden:\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 8\nAantal ballen: 4\nAantal pylonen: 4\nAfstand tussen pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAannemen van de bal:\n- open aanname, gericht naar voren.\n- snelheid houden na de aanname voor de\nvolgende actie.\nDribbelen van de bal:\n- speelbeen: Bal steeds zodanig en zo vaak\nraken dat hij in het looptempo en in goede\nrichting kan worden meegenomen \"bal aan\nelastiekje\".\n- raakvlak: Het beroeren van de bal\nafwisselend met wreef, binnen- en buitenkant\nvan de voet afhankelijk van\nrichtingsverandering.\n- over de bal heen kijken."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º (ZELFDE/ANDERE BEEN) IN VIERKANTVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Spelers 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 90º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "RATTEN EN RAVEN", "content": "Het spel wordt gespeeld met tweetallen, die recht tegenover\nelkaar staan, op een onderlinge afstand van 2 meter. Aan de ene\nkant staan de ratten en aan andere kant de raven.\nAls verteller vertelt de trainer een verhaal waarin de woorden\nratten en raven steeds voorkomen. Op het moment dat de trainer\néén van deze namen noemt, dan moet die groep zo snel mogelijk\nnaar hun achterlijn zien te lopen.De andere groep moet hen zien\nte tikken voordat zij bij hun achterlijn zijn.\nJe krijgt voor elke getikte speler 1 punt.\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nPylonen:\n- 4 om het speelveld af te bakenen.\n- 4 pylonen/hoedjes om de vrije zone aan te\ngeven.\n- 4 pylonen/hoedjes om de startlijn aan te geven.\n- 2 pylonen/hoedjes op de middenlijn aan te\ngeven\nAanwijzingen\n- als de speler de ander voor de vrije zone\nkan tikken dan heeft die een punt. Speel een\npotje tot de vijf.\n- zorg dat de spelers ook echt starten\nwanneer hun naam genoemd wordt\n- probeer er een leuk verhaal van te maken.\nNiet alleen maar ratten en raven roepen, dus\nspelen met de ''rrrrr''."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (1)", "content": "A. Spelers 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar links\"aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 4.\n- Speler 3 sluit achter speler 4 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- Idem, andersom met het andere been.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 4), Sleep (Stap 3) en Akka (binnen-voor) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "(3 : 1) OEFENING 3", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nDe aanvaller die een fout maakt wordt verdediger\nUitvoering:\n- In spelvorm 5x samenspel = 1 pnt.\n- aanraken/afpakken of lijndribbel =1 pnt.\n- wisselen van taak bij 5 pnt.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 3 spelers nemen positie in op 3 van de 4\nzijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken.\nPARTIJVORM 1:1\nMethodiek\nEén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O9', 26, '{"session_a": [{"type": "warming_up", "title": "BALGOOCHELAAR", "content": "Oefeningen, waarbij de spelers de stappen van de onderstaande\ntechnieken, op de plaats/ in voorwaartse richting moeten\nuitvoeren. De speler heeft daarbij een bal in de handen die hij, op\neen teken van de trainer, in verschillende standen langs zijn\nlichaam moet brengen..\n1. Tripling (Stap 1, 2, 3 en 4)\n2. Skipping ( Stap 1, 2, 3 en 4)\n3. Hielaanslag (Stap 1 en 2)\nOpgelet!\nDeze oefening kan ook uitgevoerd worden als aanleervorm.\nDoor de bal in verschillende posities te houden wordt er veel\ngevraagd van de rompstabiliteit van de speler. (Rompstabiliteit:\nhet stilhouden van het bovenlichaam.)\nMaterialen\nAantal spelers: 15\nAantal pylonen: 0\nAantal ballen: 15\nOrganisatie:\nDe spelers staan kris kras door elkaar in het 16-\nmeter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º (ZELFDE/ANDERE BEEN) IN VIERKANTVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Spelers 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, maar aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nVariatie\nVariatie 2: Aanbieden rechts en links\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Pirouette (Stap 4)\n- Aai-kappen achter het standbeen (Stap 3)\n- de Schijntrap (Stap 3).\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 1: Het aanleren van de techniek Pirouette (Stap 5).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: iedereen een bal\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "KRISKRASORGANISATIE (2)", "content": "Spelers voeren één van de stappen van de onderstaande\ntechnieken uit, terwijl zij met de bal aan de voet zonder elkaar te\nhinderen door het hele vak bewegen.\n- Aai buitenkant voet (Stap 1)\n- Kappen achter standbeen (Stap 1)\n- Pirouette (Stap 3)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 4\nDe pylonen vormen een rechthoek van 10 bij 8\nmtr.\nOrganisatie:\nSpelers staan kris kras door elkaar.\nDe trainer geeft eersteen beeld van de oefening\nen controleert daarna de uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (1)", "content": "A. Spelers 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar links\"aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 4.\n- Speler 3 sluit achter speler 4 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- Idem, andersom met het andere been.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Pirouette (Stap 4)\n- Aai-kappen achter het standbeen (Stap 3)\n- de Schijntrap (Stap 3).\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 2: Het aanleren van de techniek Aai kappen achter\nstandbeen (Stap 4). Het oefenen van de techniek Pirouette (Stap\n5).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: iedereen een bal\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai-kappen achter het standbeen (Stap 5A)\n- Schijntrap (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen( doet alsof hij een\ntegenstander aan de zijkant heeft).\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit en passeert daarmee de tegenstander die van de\nzijkant komt.\nC. Daarna dribbelt hij, met de bal aan de voet, richting het doel\nom vervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O9', 27, '{"session_a": [{"type": "warming_up", "title": "HIELAANSLAG-ESTAFETTE", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek in voorwaartse richting uitvoert(en) tot bij de medespeler\naan de andere kant. Ondertussen voert hij daarbij de hielslag uit,\nterwijl hij de bal met een lichte hoek in de ellebogen in de handen\nvoor het lichaam houdt. Aan de overkant gekomen geeft hij de bal\nover en zijn medespeler voert vervolgens ook de oefening in\ntegengestelde richting uit.\n1. Hielaanslag (Stap 2)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler stap 2 van de hielaanslag beheerst.\nMaterialen\nAantal spelers: 10\nAantal ballen: 2\nAantal pylonen: 4\nOrganisatie:\nDe spelers( 3 aan de ene en 2 aan de andere\nkant) staan verdeeld in 2 rijen achter de op een\nonderlinge afstand van 15 mtr. geplaatste\npylonen tegenover elkaar.De voorste speler\nheeft een bal in de handen en start de oefening\nWinnaar is de rij die het eerst de oefening\nuitgevoerd heeft\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.3 A: VOOR POSITIESPELEN (3:0)", "content": "Bij deze oefening is het belangrijk dat de speler in balbezit 2\nspeelmogelijkheden heeft.\nDe aanbiedende spelers moeten, om aanspeelbaar te kunnen zijn,\naan beide zijden vrijkomen.\nDeze spelers kunnen hierbij de bal op de volgende manier\nverwerken:\n- Links aannemen en links doorspelen\n- Links aannemen en rechts doorspelen\n- Rechts aannemen en rechts doorspelen\n- Rechts aannemen en links doorspelen.\nDe spelers hebben dan de volgende afspeelmogelijkheden:\n- Speler 1 kan op 2 en 3 spelen\n- Speler 2 kan op 1 en 3 spelen\n- Speler 3 kan op 1 en 2 spelen\nVariatie in uitvoering:\n- Inspelen met de klok mee\n- Inspelen tegen de klok in\n- Spelen op eigen intuïtie\n- Verhogen van speelsnelheid\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nmedespeler.\nAannemen:\n- Voor je liggen maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aanname, zodat de bal twee kanten\nopgespeeld kan worden.\n2 TEGEN 1\nMethodiek\nIn ieder vak van 3 aaneengeschakelde vakken staat een speler.\nDe speler in het middelste vak is de lummel.\nDe spelers in de buitenste vakken proberen de bal over te spelen\ndoor het middelste vak heen, zonder dat de lummel de bal\nonderschept.\nAls de lummel de bal onderschept moet de speler die de bal als\nlaatste aanraakte / speelde wisselen met de lummel.\nAls de bal buiten de buitenste vakken komt, wordt de speler die\nals laatste de bal raakte de lummel.\nVariatie:\n- per X-aantal keer overspelen krijgen de ''''balbezitters'' een punt\n- de bal moet in beweging blijven, dus de balbezitters mogen niet\nstil gaan staan met de bal.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: 3-tal 1 bal\nAantal pylonen: 8\nAfstand pylonen: 8 bij 8 meter\nAanwijzingen\nSpelers coachen op:\n- Schieten met de binnenkant van de voet.\n- Speelbeen loodrecht op de speelrichting.\n- Voetzool parallel met de grond."}, {"type": "techniek", "title": "LIJNDRIBBEL 3:2 MET DOEL", "content": "d.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "TWEETAL TIKKERTJE", "content": "Twee spelers vormen een tweetal door de hand van elkaar vast te houden. Met\nde vrije hand mogen ze andere spelers proberen te tikken. Een getikte speler\nsluit bij het tweetal aan. Bij 4 spelers wordt het viertal weer opgesplitst in twee\ntweetallen.\nWie blijft er over?\nOpgelet!\nHoudt de handen stevig vast.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 8 of meer spelers\nPylonen: 4 om het speelveld af te bakenen."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "C. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 4) en Akka (binnen-buiten) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O9', 28, '{"session_a": [{"type": "warming_up", "title": "OMSCHAKELINGSTIKKERTJE", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nOp een teken van de trainer probeert de speler uit de ene groep de andere\nspeler van het tweetal uit de andere groep te tikken.\nNadat hij hem getikt heeft draait hij direct van hem weg en versnelt naar de\nzijlijn. De andere speler probeert op zijn beurt de eerste speler, nog voordat hij\nde zijlijn heeft gepasseerd, te tikken.\nDifferentiatie gemakkelijk:\n- het spel “koe-kopen”.\nDifferentiatie moeilijk:\n- er kan gevarieerd worden door spelers met een bal aan de zijlijn te laten staan,\nom een kaats aan te gaan met de weggedraaide speler. Hij komt hierbij als het\nware in de bal. Omschakeling met bal (1)\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- de afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "2 TEGEN 1", "content": "In ieder vak van 3 aaneengeschakelde vakken staat een speler.\nDe speler in het middelste vak is de lummel.\nDe spelers in de buitenste vakken proberen de bal over te spelen\ndoor het middelste vak heen, zonder dat de lummel de bal\nonderschept.\nAls de lummel de bal onderschept moet de speler die de bal als\nlaatste aanraakte / speelde wisselen met de lummel.\nAls de bal buiten de buitenste vakken komt, wordt de speler die\nals laatste de bal raakte de lummel.\nVariatie:\n- per X-aantal keer overspelen krijgen de ''''balbezitters'' een punt\n- de bal moet in beweging blijven, dus de balbezitters mogen niet\nstil gaan staan met de bal.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: 3-tal 1 bal\nAantal pylonen: 8\nAfstand pylonen: 8 bij 8 meter\nAanwijzingen\nSpelers coachen op:\n- Schieten met de binnenkant van de voet.\n- Speelbeen loodrecht op de speelrichting.\n- Voetzool parallel met de grond.\nTEGENSTANDER VANAF DE ZIJKANT: IN EEN VIERKANTSVORM\nMethodiek\nSpelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Pirouette (Stap 4)\n- Aai-kappen achter het standbeen (Stap 3)\n- de Schijntrap (Stap 3).\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het aanleren van de techniek De schijntrap (Stap 4).\nHet oefenen van de techniek Aai kappen achter standbeen (Stap\n4) en Pirouette (Stap 5).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: iedereen een bal\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai-kappen achter het standbeen (Stap 5A)\n- Schijntrap (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen( doet alsof hij een\ntegenstander aan de zijkant heeft).\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit en passeert daarmee de tegenstander die van de\nzijkant komt.\nC. Daarna dribbelt hij, met de bal aan de voet, richting het doel\nom vervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}], "session_b": [{"type": "warming_up", "title": "LIJNORGANISATIE (2)", "content": "Eén van de stappen van de onderstaande technieken dient, heen\nen terug tussen de lange zijden van de rechthoek, uitgevoerd te\nworden.\n- Aai buitenkant voet (Stap 1)\n- Kappen achter standbeen (Stap 1)\n- Pirouette (Stap 3)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 2-16 (per speler twee pylonen)\nTwee rijen pylonen op een onderlinge afstand\nvan 8 mtr.\nOrganisatie:\nDe trainer geeft eerst een beeld van de oefening\nen controleert daarna de uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "1. (3 : 1 + 2)", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nWanneer de verdediger de bal onderschept dan moet hij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 1 verdediger en 1 aanvaller mee naar het andere\nveld. Nu moeten de drie verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de aanvaller de bal kan\nveroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (10m bij 8m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O9', 29, '{"session_a": [{"type": "warming_up", "title": "SPIEGELEN (1)", "content": "Oefeningen, waarbij de speler(s) de door de tegenstander uitgevoerde stappen\nvan de onderstaande technieken, op de plaats, nadoet(n).\n1. Trippling (Stap 1, 2)\n2. Skipping (Stap 1, 2, 3)\n3. Hielaanslag ( Stap 1)\nOpgelet!\n- alleen uitvoeren als de spelers bekend zijn met bovenstaande technieken.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nDe pylonen vormen een rechte lijn van 2 mtr.\nOrganisatie:\n- de spelers staan hierbij recht tegenover één speler die de leiding heeft. Zij\nmoeten daarbij zijn bewegingen volgen (spiegelen)."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- Pirouette (Stap 4)\n- Aai-kappen achter het standbeen (Stap 3)\n- de Schijntrap (Stap 3).\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai kappen achter\nstandbeen (Stap 4), Pirouette (Stap 5) en De schijntrap (Stap 4).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: iedereen een bal\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu met het andere been uitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "PAALTJES VOETBAL 1", "content": "Het spel wordt gespeeld met 1 bal en elke speler start met 3\npunten. Alle spelers krijgen ergens in het vak een pylon te\nverdedigen. De spelers moeten proberen de pylon van elkaar\nomver te schieten. Gebeurt dit dan gaat er bij de desbetreffende\nspeler een punt af . Uiteindelijk blijft er 1 speler, de winnaar, over.\nVariatie:\nEen tweede bal in het spel brengen.\nOpgelet!\nBlijf niet voor je pylon hangen!\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nPylon: voor iedere speler 1\nBallen: 1-2\nAanwijzingen\nAls een speler geen punten meer heeft dan\ngaat hij aan de kant staan.\nSTAP 2.2 A: AANBIEDEN, HEEN/TERUG IN LIJNVORM COMBINATIE\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 speelt de bal met de binnenkant van de linker-\n/rechtervoet.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 2 kaatst de bal met de binnenkant van de linker-\n/rechtervoet terug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 kaatst de bal met de binnenkant van de linker-\n/rechtervoet.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet,\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- De Overstap (Stap 3)\n- Kappen buitenkant voet (Stap 1+2)\n- Binnen-buitenkant wegdraai (Stap 1+2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 4),\nKappen buitenkant voet (Stap 3) en Binnen buiten wegdraai (Stap\n3+4).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu de oefening met het andere been\nuitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\n- Binnen-buitenkant wegdraai (Stap 4)\nA. Speler 1 start de oefening door de bal met de rechter\nbinnenkant van de voet op de aanbiedende speler 2 te\npassen(deze doet alsof hij een speler in de rug heeft).\nB. Speler 2 ontvangt de bal en voert vervolgens één van de\nbovengenoemde technieken uit.\nC. Daarna dribbelt hij richting doel om vervolgens hierop af te\nronden.\nD. Speler 2 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 loopt door naar de volgende pylon en\nneemt de positie over van speler 2.\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\nIdem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O9', 30, '{"session_a": [{"type": "test", "title": "WENDBAARHEIDSTEST 1", "content": "Voor deze test wordt in het strafschopgebied, tussen de doellijn\nen de rand van het gebied, een parcours ( zie tekening) uitgezet.\nHet protocol voor deze test luidt als volgt:\nDe test start vanuit buikligging. Vervolgens wordt het hele traject\nin korte sprintjes, van pylon naar pylon, afgelegd.\nDe pylonen worden daarbij,tot het bereiken van de finish, telkens\nzo kort mogelijk gerond.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen:8\nAfstand tussen de pylonen:gebruik de\naangegeven lijnen en verdeel de tussenliggende\nruimte gelijkmatig\nSchrijfbenodigdheden\nAanwijzingen\n- ontwikkel, zowel heen als terug, een zo\nhoog mogelijke snelheid\n- draai kort om de pylon\n- neem minimaal 2-3 minuten rust tussen\ntwee testen"}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Pirouette (Stap 5)\n- Aai achter standbeen (Stap 4)\n- De Schijntrap (Stap 4)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai kappen achter\nstandbeen (Stap 4), Pirouette (Stap 5) en De schijntrap (Stap 4).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "LIJNDRIBBEL 3:2 MET DOEL", "content": "d.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "SIGNAALORGANISATIE (2)", "content": "De spelers voeren op een teken één van de stappen van de\nonderstaande technieken uit. De technieken zijn gekoppeld aan\neen nummer (1,2,3,4 etc.) of een naam en dienen verspreid over\nhet hele vak uitgevoerd te worden.\n- Schaar en Pirouette (Stap 2)\n- Sleep (Stap 1)\n- Uitstappen/meenemen (Stap 2)\n- De Overstap (Stap 2)\n- De Schijntrap (Stap 2)\nOpgelet!\n- alleen gebruiken als de spelers bekend zijn met de oefeningen.\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 4\nDe pylonen vormen een rechthoek van 10 bij 8\nmtr.\nOrganisatie:\n- de trainer geeft eerst vooraf een beeld van de\nuit te voeren techniek(en) en controleert daarna\nde uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek, zie\ntechnieklijst.\n2 TEGEN 1\nMethodiek\nIn ieder vak van 3 aaneengeschakelde vakken staat een speler.\nDe speler in het middelste vak is de lummel.\nDe spelers in de buitenste vakken proberen de bal over te spelen\ndoor het middelste vak heen, zonder dat de lummel de bal\nonderschept.\nAls de lummel de bal onderschept moet de speler die de bal als\nlaatste aanraakte / speelde wisselen met de lummel.\nAls de bal buiten de buitenste vakken komt, wordt de speler die\nals laatste de bal raakte de lummel.\nVariatie:\n- per X-aantal keer overspelen krijgen de ''''balbezitters'' een punt\n- de bal moet in beweging blijven, dus de balbezitters mogen niet\nstil gaan staan met de bal.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: 3-tal 1 bal\nAantal pylonen: 8\nAfstand pylonen: 8 bij 8 meter\nAanwijzingen\nSpelers coachen op:\n- Schieten met de binnenkant van de voet.\n- Speelbeen loodrecht op de speelrichting.\n- Voetzool parallel met de grond."}, {"type": "techniek", "title": "A. TEGENSTANDER NAAST JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nB. TEGENSTANDER NAAST JE: IN LIJNVORM HEEN TERUG\nMethodiek\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen achter het standbeen (Stap 2)\n- Kappen binnenkant voet (Stap 3)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O9', 31, '{"session_a": [{"type": "test", "title": "SPEEDLADDER (1)", "content": "Is een oefening, waarbij de voorwaartse vormen worden\naangeleerd in de speedladder. De oefening is opgebouwd van\ngrove motoriek naar de fijne motoriek. Dat wil zeggen binnen de\nlooptraining, er wordt gewerkt van een skipping naar skipping 45\ngraden en vervolgens naar kort voetenwerk.\nStap 1: Eén voetje in het raam plaatsen.\nStap 2: Twee voetjes in het raam plaatsen.\nStap 3: Drie voetjes in het raam plaatsen.\nDifferentiatie:\nStroop de ladder op, zodat er door de spelers ten alle tijden een\nskipping ingezet moet worden.\nLet op!\nDeze vormen kunnen spelenderwijs worden aangeleerd.\nMaterialen\nAantal spelers: het gehele team.\nAantal speedladders:\nEén, bij voorkeur twee.\nAantal pylonnen:\nEén\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Pirouette (Stap 5)\n- Aai achter standbeen (Stap 4)\n- De Schijntrap (Stap 4)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai kappen achter\nstandbeen (Stap 4), Pirouette (Stap 5) en De schijntrap (Stap 4).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai-kappen achter het standbeen (Stap 5A)\n- Schijntrap (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen( doet alsof hij een\ntegenstander aan de zijkant heeft).\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit en passeert daarmee de tegenstander die van de\nzijkant komt.\nC. Daarna dribbelt hij, met de bal aan de voet, richting het doel\nom vervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "LIJNEN SPEL", "content": "De spelers staan met de bal aan de voet op een door de trainer\naangegeven lijn van het 16- meter gebied. Op zijn teken dribbelen\nde spelers naar een door de trainer aangegeven andere lijn.\nOpgelet!\nGeen 16- meter gebied beschikbaar, maak dan gebruik van\nverschillend gekleurde pylonen of hoedjes om daarmee lijnen te\nvormen\nMaak bij de\" jongste jeugd\" gebruik van nummers.\nVariatie:\n- Geef elke speler bij aanvang 3 punten en haal bij de laatste\ntelkens 1 punt af. Winnaar is ook nu weer degene die over blijft.\n- Laatste valt steeds af en winnaar is degene die over blijft (alleen\ndoen als afsluiting van een training).\nMaterialen\nAantal spelers: 4-14\nAantal pylonen: 10 (om eventueel de lijnen aan\nte geven)\nAantal ballen: elke speler 1 bal\nAanwijzingen\nSpelers coachen op:\n- Draai eerst proef.\n- De bal moet wel steeds op de lijn onder de\nvoet stil liggen.\nSTAP 2.2 A: AANBIEDEN, HEEN/TERUG IN LIJNVORM COMBINATIE\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 speelt de bal met de binnenkant van de linker-\n/rechtervoet.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 2 kaatst de bal met de binnenkant van de linker-\n/rechtervoet terug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 kaatst de bal met de binnenkant van de linker-\n/rechtervoet.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 4) en\nAkka (buiten-binnen) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "1. (3 : 1 + 2)", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nWanneer de verdediger de bal onderschept dan moet hij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 1 verdediger en 1 aanvaller mee naar het andere\nveld. Nu moeten de drie verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de aanvaller de bal kan\nveroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (10m bij 8m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken\nPARTIJVORM 1:1\nMethodiek\nEén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O9', 32, '{"session_a": [{"type": "warming_up", "title": "TENNISBALLENSPEL", "content": "Bij deze oefening wordt het ‘omschakelmoment’ van een speler\naangeleerd en getraind. Door deze oefening wordt een speler\nhandig in het lichtvoetig draaien. Tevens benadrukt deze oefening\nhet ‘laag zitten’ bij het wegdraaien bij de speler.\nOrganisatieuitleg:\nEr zijn bij het spel 4 pylonnen, 4 tennisballen en één hoepel\naanwezig. De pylonnen staan in een plusvorm en op de pylonnen\nliggen de tennisballen.\nSpeluitleg:\nDe speler begint in de hoepel, op een commando van de trainer\nstart de speler naar de eerste pylon. De speler pakt de tennisbal\nmet de rechterhand en geeft de bal over in zijn linkerhand en legt\nhem vervolgens in de hoepel. Vanuit de hoepel vertrekt de zelfde\nspeler naar de tweede pylon en pakt tevens weer een tennisbal\nvan de tweede pylon met zijn rechterhand, geeft deze weer over\nnaar zijn linkerhand en legt vervolgens de tennisbal weer in de\nhoepel. De speler vervolgt de zelfde volgorde ook bij de derde en\nvierde pylon.\nDifferentiatie:\nBiedt de vorm ook aan in een wedstrijdvorm, zodat de oefening\nook op maximale snelheid uitgevoerd moet worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal organisaties:\nZoveel als mogelijk.\nAantal pylonnen voor één organisatie: 4\npylonnen.\nAantal hoepels voor één organisatie:\n1 hoepel\nOrganisatie:\nPer situatie voert één speler de oefening uit.\nAanwijzingen\nLet op!\nZorg ervoor dat de oefening volledig wordt\nuitgevoerd. Dat de speler tevens bij elke\nomschakeling ‘laag zit’ (gebogen knieën\nheeft)."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "A. TEGENSTANDER NAAST JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nB. TEGENSTANDER NAAST JE: IN LIJNVORM HEEN TERUG\nMethodiek\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen achter het standbeen (Stap 2)\n- Kappen binnenkant voet (Stap 3)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "LIJNDRIBBEL 3:2 MET DOEL", "content": "d.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "SIGNAALORGANISATIE (3)", "content": "Spelers voeren op een teken één van de stappen van de\nonderstaande technieken uit. De technieken zijn gekoppeld aan\neen nummer (1,2,3 etc.) of een naam en dienen verspreid over\nhet hele vak uitgevoerd te worden.\n- Aai buitenkant voet (Stap 1)\n- Kappen achter standbeen (Stap 1)\n- Pirouette (Stap 3)\nOpgelet!\n- alleen gebruiken als de spelers bekend zijn met de oefeningen.\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 4\nDe pylonen vormen een rechthoek van 10 bij 8\nmtr.\nOrganisatie:\n- de trainer geeft eerst vooraf een beeld van de\nuit te voeren techniek(en) en controleert daarna\nde uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek, zie\ntechnieklijst.\n2 TEGEN 1\nMethodiek\nIn ieder vak van 3 aaneengeschakelde vakken staat een speler.\nDe speler in het middelste vak is de lummel.\nDe spelers in de buitenste vakken proberen de bal over te spelen\ndoor het middelste vak heen, zonder dat de lummel de bal\nonderschept.\nAls de lummel de bal onderschept moet de speler die de bal als\nlaatste aanraakte / speelde wisselen met de lummel.\nAls de bal buiten de buitenste vakken komt, wordt de speler die\nals laatste de bal raakte de lummel.\nVariatie:\n- per X-aantal keer overspelen krijgen de ''''balbezitters'' een punt\n- de bal moet in beweging blijven, dus de balbezitters mogen niet\nstil gaan staan met de bal.\nMaterialen\nAantal spelers: 6-10\nAantal ballen: 3-tal 1 bal\nAantal pylonen: 8\nAfstand pylonen: 8 bij 8 meter\nAanwijzingen\nSpelers coachen op:\n- Schieten met de binnenkant van de voet.\n- Speelbeen loodrecht op de speelrichting.\n- Voetzool parallel met de grond."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 4), Sleep (Stap 3) en Akka (binnen-voor) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Akka (buiten-binnen) (Stap 3A)\n- Schaar (Stap 5A)\nDribbelen buitenkant voet, inzet beweging binnenkant voet:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\n- Uitstappen/meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna dribbelt hij, met de bal aan de voet, richting doel om\nvervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE -pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}]}'::jsonb)
